insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-area-p4-0002', 'math-area', 4, 'quest', 'A rectangle is 12 cm long and 8 cm wide. Its length is increased by 2 cm. What is the new area?', '["96","112","104","120"]', 1, 'The new length is 12 + 2 = 14 cm, so the area is 14 × 8 = 112 cm².', '112 cm² — a longer rectangle!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-area-p4-0003', 'math-area', 4, 'quest', 'A rectangle is 15 cm long and 9 cm wide. Its width is increased by 3 cm. What is the new perimeter?', '["48","54","42","60"]', 1, 'The new width is 9 + 3 = 12 cm, so the perimeter is 2 × (15 + 12) = 54 cm.', '54 cm — a wider rectangle!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-area-p4-0004', 'math-area', 4, 'quest', 'An L-shaped room has a perimeter of 40 m. Five of its sides are 12 m, 8 m, 4 m, 3 m and 8 m. How long is the sixth side?', '["5","6","4","3"]', 0, 'The five known sides add up to 12 + 8 + 4 + 3 + 8 = 35 m, so the last side is 40 − 35 = 5 m.', '5 m — the missing side found!', 'bank') on conflict (id) do nothing;
