insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0003', 'math-angles', 3, 'quest', 'Railway tracks are an example of which kind of lines?', '["Parallel lines","Perpendicular lines","Curved lines","Slanted lines"]', 0, 'The two rails stay the same distance apart and never meet.', 'Choo choo — parallel tracks!', 'bank') on conflict (id) do nothing;
