insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0005', 'math-angles', 3, 'quest', 'Which of these describes two parallel lines?', '["They meet at a corner","They stay the same distance apart","They cross like an X","They form a T shape"]', 1, 'Parallel lines stay the same distance apart and never meet.', 'Same distance apart — forever friends!', 'bank') on conflict (id) do nothing;
