insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0008', 'math-angles', 3, 'fresh', 'Which of these is a pair of parallel lines?', '["The edges of a door frame that meet at the corner","The opposite sides of a book","The hands of a clock","The two lines of the letter X"]', 1, 'The opposite sides of a book stay the same distance apart.', 'A book''s sides — parallel partners!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0009', 'math-angles', 3, 'fresh', 'Which of these is a pair of perpendicular lines?', '["The opposite sides of a table","The adjacent sides of a table","The rails of a train track","The lines of the letter V"]', 1, 'The sides that meet at a table corner form a right angle.', 'Table corners — right angles everywhere!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0010', 'math-angles', 3, 'fresh', 'Which drawing shows two parallel lines?', '["Two lines that meet at a point","Two lines that cross in the middle","Two lines that run side by side without meeting","Two lines that form a right angle"]', 2, 'Parallel lines run side by side and never meet.', 'Side by side — never meeting!', 'bank') on conflict (id) do nothing;
