insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-angles-p3-0013', 'math-angles', 3, 'fresh', 'A triangle has 3 angles. If one is a right angle, how many angles are left?', '["1","2","3","0"]', 1, '3 − 1 = 2 angles are left.', '2 angles left — still a triangle!', 'bank') on conflict (id) do nothing;
