insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-ntuc-p4-0043', 'math-ntuc', 4, 'retry', 'A red bag has 6 times as many marbles as a blue bag. Together they have 1,085 marbles. How many marbles are in the blue bag?', '["155","930","310","465"]', 0, '1,085 ÷ 7 = 155 marbles in the blue bag.', 'Blue bag: one-five-five!', 'bank') on conflict (id) do nothing;
