insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('math-hawker-p3-0001', 'math-hawker', 3, 'quest', 'Pack A has 2 notebooks for $4. Pack B has 3 notebooks for $5.40. Which pack is cheaper for one notebook?', '["Pack A","Pack B","They cost the same","Cannot tell"]', 1, 'Pack A: $4 ÷ 2 = $2.00 each. Pack B: $5.40 ÷ 3 = $1.80 each. Pack B is cheaper!', 'Pack B wins the bargain race!', 'bank') on conflict (id) do nothing;
