insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p3-0002', 'eng-spelling', 3, 'quest', 'Mina wrote a card to her best ___. Which spelling is right?', '["freind","friend","frind","frend"]', 1, 'Friend has “ie” — “I am your friend till the end!”', 'A friend in need is a friend indeed!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p3-0003', 'eng-spelling', 3, 'quest', 'Choose the correct spelling of the word that means “from one side to the other”.', '["throo","thru","through","threw"]', 2, 'Through has “ough” — the tricky part hides in the middle.', 'You made it through — nicely done!', 'bank') on conflict (id) do nothing;
