insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p3-0005', 'eng-spelling', 3, 'quest', 'Pick the word that is spelt right.', '["together","togther","togeather","togetha"]', 0, 'Together is to-get-her — three little parts in one word.', 'Together we spell it right!', 'bank') on conflict (id) do nothing;
