insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0003', 'eng-spelling', 4, 'quest', 'I ___ you can do it if you keep trying.', '["beleve","belive","beleive","believe"]', 3, 'Believe has “ie” — “believe” rhymes with “receive”!', 'I believe in your spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0004', 'eng-spelling', 4, 'quest', 'Riding a ___ is good exercise.', '["bicycle","bycicle","bicicle","bysicle"]', 0, 'Bicycle is b-i-c-y-c-l-e — “bi” means two wheels!', 'Two wheels, one perfect spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0005', 'eng-spelling', 4, 'quest', 'Check the ___ to see what day it is.', '["calandar","calendar","calander","calender"]', 1, 'Calendar ends in “ar” — “calend-ar”, like “car”!', 'Mark this day on the calendar — you spelt it right!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0006', 'eng-spelling', 4, 'fresh', 'The ___ keeps the school safe at night.', '["gaurd","gard","guard","gurd"]', 2, 'Guard is g-u-a-r-d — the “u” stands guard too!', 'On guard — and on point with spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0007', 'eng-spelling', 4, 'fresh', 'What is the ___ of that tall building?', '["hieght","heigt","hight","height"]', 3, 'Height is h-e-i-g-h-t — “ei” after “h”!', 'You have reached new heights!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0008', 'eng-spelling', 4, 'fresh', 'Singapore is an ___.', '["island","iland","islend","islan"]', 0, 'Island has a silent “s” — “is-land”!', 'Island life, island spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0009', 'eng-spelling', 4, 'fresh', 'Reading books gives you ___.', '["knowlege","knowledge","knowledg","nowledge"]', 1, 'Knowledge ends in “dge” — “know” + “ledge”!', 'Knowledge is power — and so is spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0010', 'eng-spelling', 4, 'fresh', 'We borrow books from the ___.', '["librery","libary","library","librare"]', 2, 'Library is l-i-b-r-a-r-y — “brary” like “January”!', 'Shh… your spelling is library-quiet and perfect!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0011', 'eng-spelling', 4, 'fresh', 'The ___ puppy chewed my shoes!', '["noghty","naugthy","naugty","naughty"]', 3, 'Naughty is n-a-u-g-h-t-y — “augh” makes the “or” sound!', 'Naughty puppy, nice spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0012', 'eng-spelling', 4, 'fresh', 'Our ___ bakes the best cookies.', '["neighbour","neigbour","naybour","nieghbour"]', 0, 'Neighbour is n-e-i-g-h-b-o-u-r — “neigh” like a horse!', 'Good neighbours, great spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0013', 'eng-spelling', 4, 'fresh', 'What a special ___ — a birthday party!', '["ocasion","occasion","occassion","ocassion"]', 1, 'Occasion has double “c” and single “s” — “oc-ca-sion”!', 'What an occasion — perfectly spelt!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0014', 'eng-spelling', 4, 'fresh', 'North is the ___ of south.', '["opposit","oposite","opposite","oppisite"]', 2, 'Opposite has double “p” — “op-po-site”!', 'Quite the opposite of wrong!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0015', 'eng-spelling', 4, 'fresh', 'A camera is a useful ___ on holiday.', '["posession","possesson","possesion","possession"]', 3, 'Possession has double “s” twice — “pos-ses-sion”!', 'You possess perfect spelling!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0016', 'eng-spelling', 4, 'warm', 'The shopping ___ is in the middle of town.', '["centa","center","centre","sentre"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0017', 'eng-spelling', 4, 'warm', 'I am ___ that the show starts at 7pm.', '["sertain","curtain","certan","certain"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0018', 'eng-spelling', 4, 'warm', 'Can you ___ your favourite animal to me?', '["describe","describ","discrbe","discribe"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0019', 'eng-spelling', 4, 'warm', 'The magician made the rabbit ___.', '["disapper","disappear","dissapear","disapear"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0020', 'eng-spelling', 4, 'warm', 'I love ice cream, ___ chocolate flavour.', '["exspecially","especiallly","especially","especialy"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0021', 'eng-spelling', 4, 'warm', 'My birthday is in ___, the shortest month.', '["Februray","Februery","Febuary","February"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0022', 'eng-spelling', 4, 'warm', 'Please move ___ so we can see the board.', '["forward","forword","foreward","foward"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0023', 'eng-spelling', 4, 'warm', 'We learn ___ in English class.', '["gramar","grammar","gramma","grammer"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0024', 'eng-spelling', 4, 'retry', 'I will ___ finish my homework tonight.', '["probably","probly","probabely","probely"]', 0, 'Probably is p-r-o-b-a-b-l-y — “prob-a-bly”!', 'Probably the best spelling today!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0025', 'eng-spelling', 4, 'retry', 'Please ___ the two words with a line.', '["seperate","separate","separete","seprate"]', 1, 'Separate has “a” in the middle — “there is a rat in separate”!', 'Separate the right from the wrong — done!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0026', 'eng-spelling', 4, 'retry', 'What a nice ___ — a new puppy!', '["surprize","suprise","surprise","suprize"]', 2, 'Surprise is s-u-r-p-r-i-s-e — “sur-prise”!', 'Surprise! Your spelling is brilliant!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0027', 'eng-spelling', 4, 'retry', 'We will go to the zoo ___.', '["tommorrow","tomoro","tomorow","tomorrow"]', 3, 'Tomorrow has double “m” and double “r” — “tom-or-row”!', 'Tomorrow is another day — and another win!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0028', 'eng-spelling', 4, 'retry', 'Take an ___ in case it rains.', '["umbrella","umberlla","umbrellaa","umbrela"]', 0, 'Umbrella has double “l” — “um-brel-la”!', 'Rain or shine, your spelling is fine!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-spelling-p4-0029', 'eng-spelling', 4, 'retry', '___ is the middle of the school week.', '["Wendsday","Wednesday","Wensday","Wednesdey"]', 1, 'Wednesday is W-e-d-n-e-s-d-a-y — “wed-nes-day”!', 'Hump day? More like champ day!', 'bank') on conflict (id) do nothing;
