insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0001', 'eng-tense', 3, 'quest', '___ am the fastest runner in my class.', '["I","My","Mine","Me"]', 0, 'Use “I” when you are the one doing the action.', 'I am the fastest — and the smartest with pronouns!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0002', 'eng-tense', 3, 'quest', 'The teacher gave the prize to ___ because we won.', '["we","us","our","ours"]', 1, 'After “to”, use “us” — the receiving word!', 'A prize for us — and for your grammar!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0003', 'eng-tense', 3, 'quest', 'This red bicycle is ___. I got it for my birthday.', '["I","my","mine","me"]', 2, '“Mine” stands alone — it means “my bicycle”!', 'Mine, all mine — and all correct!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0004', 'eng-tense', 3, 'quest', 'Sara forgot ___ umbrella, so she shared mine.', '["herself","she","hers","her"]', 3, '“Her umbrella” — “her” goes before the thing it owns!', 'Sharing is caring — and so is good grammar!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0005', 'eng-tense', 3, 'quest', 'The cat cleaned ___ after playing in the mud.', '["itself","it","its","it’s"]', 0, '“Itself” means the cat did it to its own body!', 'A clean cat and a clean answer!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0006', 'eng-tense', 3, 'quest', 'We built the treehouse by ___.', '["ours","ourselves","us","we"]', 1, '“Ourselves” means we did it with no help!', 'Built it ourselves — and answered it ourselves!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0007', 'eng-tense', 3, 'quest', '___ apples on this plate are sweet. Try one!', '["Those","This","These","That"]', 2, '“These” is for things that are near and more than one!', 'These apples are sweet — and so is your answer!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0008', 'eng-tense', 3, 'quest', 'Look at ___ birds over there! They are flying south.', '["this","these","that","those"]', 3, '“Those” is for things that are far away and more than one!', 'Those birds fly far — and your grammar flies high!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0009', 'eng-tense', 3, 'quest', 'There isn’t ___ milk left. We need to buy more.', '["any","many","few","some"]', 0, 'Use “any” in a “not” sentence — “isn’t any”!', 'Not any milk — but plenty of brains!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0010', 'eng-tense', 3, 'quest', 'How ___ books did you borrow from the library?', '["much","many","little","less"]', 1, '“Many” goes with things you can count, like books!', 'Many books, many right answers!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0011', 'eng-tense', 3, 'quest', 'The cat is hiding ___ the bed.', '["in","at","under","on"]', 2, '“Under” means below something — the cat is below the bed!', 'Found the cat — and the right answer!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0012', 'eng-tense', 3, 'quest', 'We will meet ___ the library after school.', '["in","on","under","at"]', 3, '“At” is for a place — “at the library”!', 'Meet you at the library — with the right answer!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('eng-tense-p3-0013', 'eng-tense', 3, 'quest', 'You like ice cream, ___?', '["don’t you","are you","isn’t it","do you"]', 0, '“You like” is positive, so the tag is negative: “don’t you?”', 'You like ice cream, don’t you? I knew it!', 'bank') on conflict (id) do nothing;
