insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p3-0025', 'sci-classification', 3, 'retry', 'Yeast is used to make bread rise. Yeast is a…', '["fungus","plant","animal","bacterium"]', 0, 'Yeast is a tiny fungus. It helps bread rise.', 'Yeast makes bread fluffy — thank a fungus!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p3-0026', 'sci-classification', 3, 'retry', 'Frogs are amphibians because they…', '["live in water and on land","have feathers","give birth to live young","have scales"]', 0, 'Amphibians live in water when young and on land as adults.', 'Frogs start in water and hop onto land!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p3-0027', 'sci-classification', 3, 'retry', 'Which of these is NOT an insect?', '["Earthworm","Bee","Grasshopper","Ladybird"]', 0, 'An earthworm has no legs and no wings. It is not an insect.', 'Worms wriggle — no legs needed!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p3-0028', 'sci-classification', 3, 'retry', 'A chart has the headings ''Lives in water'' and ''Lives on land''. A frog goes in…', '["Both groups — it lives in water and on land","Only ''Lives in water''","Only ''Lives on land''","Neither group"]', 0, 'Frogs live in water and on land, so they fit both groups.', 'Frogs are double agents of the pond!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p3-0029', 'sci-classification', 3, 'retry', 'Which of these animals is a mammal?', '["Dog","Eagle","Snake","Goldfish"]', 0, 'A dog has fur and feeds its babies milk, so it is a mammal.', 'Dogs are mammals — and the best friends!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0001', 'sci-classification', 4, 'quest', 'A plant makes spores but never makes flowers or seeds. Which group is it in?', '["Non-flowering plants","Flowering plants","Fungi","Bacteria"]', 0, 'Plants that make spores instead of seeds are non-flowering plants, like ferns.', 'Spores are the fern''s secret seeds!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0002', 'sci-classification', 4, 'quest', 'A scientist finds a living thing that feeds on dead wood and has no chlorophyll. What is it most likely to be?', '["A fungus","A flowering plant","A moss","An alga"]', 0, 'Fungi feed on dead matter and have no chlorophyll, so they cannot make food like plants.', 'Fungi are nature''s clean-up crew!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0003', 'sci-classification', 4, 'quest', 'An animal has fur, gives birth to live young, and lives in the sea. Which group is it in?', '["Mammals","Fish","Reptiles","Amphibians"]', 0, 'Fur and live young mean mammal — even in the sea, like a dolphin.', 'Sea mammals are mammals that said goodbye to land!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0004', 'sci-classification', 4, 'quest', 'An animal has six legs, two wings and three body parts. What is it?', '["An insect","A spider","A worm","A snail"]', 0, 'Six legs and three body parts tell you it is an insect.', 'Six legs, three parts — insect all the way!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0005', 'sci-classification', 4, 'quest', 'A chart sorts animals using two questions: ''Does it have feathers?'' then ''Can it fly?'' Where does an ostrich go?', '["Has feathers, cannot fly","Has feathers, can fly","Has scales, cannot fly","Has fur, cannot fly"]', 0, 'An ostrich has feathers but cannot fly, so it goes in ''Has feathers'' then ''Cannot fly''.', 'Ostriches are birds that prefer running!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0006', 'sci-classification', 4, 'fresh', 'Which two plants belong to the same group?', '["Fern and moss","Rose and fern","Mushroom and moss","Fern and mushroom"]', 0, 'Ferns and mosses are both non-flowering plants.', 'Ferns and mosses — the no-flower club!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0007', 'sci-classification', 4, 'fresh', 'A plant has flowers and makes seeds inside fruits. Which group is it in?', '["Flowering plants","Non-flowering plants","Fungi","Bacteria"]', 0, 'Flowers and seeds in fruits mean it is a flowering plant.', 'Flowers are how plants show off!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0008', 'sci-classification', 4, 'fresh', 'Why are fungi grouped apart from plants?', '["They cannot make their own food","They grow in soil","They have stems","They are small"]', 0, 'Plants make food with chlorophyll. Fungi cannot, so they are a different group.', 'Fungi march to their own beat!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0009', 'sci-classification', 4, 'fresh', 'Which of these is a helpful bacterium?', '["The one that makes yoghurt","The one that causes flu","The one that rots teeth","The one that makes food go bad"]', 0, 'Not all bacteria are harmful — some help make yoghurt.', 'Good bacteria help make your breakfast!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0010', 'sci-classification', 4, 'fresh', 'A platypus lays eggs but feeds its babies milk. Which group is it in?', '["Mammals","Birds","Reptiles","Fish"]', 0, 'Feeding babies milk makes it a mammal, even though it lays eggs.', 'The platypus breaks all the rules!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0011', 'sci-classification', 4, 'fresh', 'Which animal is an amphibian?', '["Toad","Lizard","Crab","Starfish"]', 0, 'A toad lives in water when young and on land as an adult.', 'Toads hop between two worlds!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0012', 'sci-classification', 4, 'fresh', 'A centipede has one pair of legs on each body segment — many more than six legs. Is it an insect?', '["No, it has too many legs","Yes, it is an insect","Yes, it is a spider","No, it is a fish"]', 0, 'Insects have exactly six legs. A centipede has many more, so it is not an insect.', 'Centipedes have legs to spare!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0013', 'sci-classification', 4, 'fresh', 'A ladybird has six legs and a hard shell over its wings. What is it?', '["An insect","A spider","A snail","A crab"]', 0, 'A ladybird has six legs and three body parts.', 'Ladybirds are spotty little insects!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0014', 'sci-classification', 4, 'fresh', 'A scientist sorts animals by ''Has a backbone'' and ''Has no backbone''. A worm goes in…', '["Has no backbone","Has a backbone","Has wings","Has feathers"]', 0, 'A worm has no backbone, so it goes in the ''Has no backbone'' group.', 'Worms are spineless — literally!', 'bank') on conflict (id) do nothing;
