insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-classification-p4-0025', 'sci-classification', 4, 'retry', 'A mushroom grows on a dead tree trunk. What does this tell you about mushrooms?', '["They feed on dead matter","They make food from sunlight","They are flowering plants","They need flowers to grow"]', 0, 'Mushrooms feed on dead matter, so they are fungi, not plants.', 'Dead wood is a mushroom''s dinner!', 'bank') on conflict (id) do nothing;
