insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p3-0001', 'sci-materials', 3, 'quest', 'Which of these is a material?', '["Wood","Water","Air","Light"]', 0, 'Wood is a material used to make things. Water and air are not materials for building.', 'Wood comes from trees — nature''s building blocks!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p3-0002', 'sci-materials', 3, 'quest', 'Which material is strong enough to hold up a heavy bookshelf?', '["Metal","Paper","Tissue","Cotton wool"]', 0, 'Metal is strong and does not break easily under heavy things.', 'Metal shelves hold a whole library!', 'bank') on conflict (id) do nothing;
