insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p3-0029', 'sci-materials', 3, 'retry', 'A shopping bag must carry heavy groceries without tearing. Which material is best?', '["Thick plastic","Thin paper","Tissue","Cotton wool"]', 0, 'Thick plastic is strong enough to carry heavy things.', 'Strong bags save the groceries!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0001', 'sci-materials', 4, 'quest', 'Which of these is a synthetic material — one made by people, not found in nature?', '["Plastic","Wood","Cotton","Wool"]', 0, 'Plastic is made by people from oil. Wood, cotton and wool come from nature.', 'Plastic is people-made — clever chemistry!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0002', 'sci-materials', 4, 'quest', 'A shelf must hold 20 heavy books without bending. Which material and why?', '["Metal, because it is strong","Paper, because it is light","Rubber, because it is flexible","Cloth, because it is soft"]', 0, 'A shelf needs strength to hold heavy books without bending, so metal is best.', 'Metal shelves never sag under homework!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0003', 'sci-materials', 4, 'quest', 'A tent must keep rain out and be light to carry. Which material is the best choice?', '["Waterproof nylon fabric","Cotton cloth","Paper","Cardboard"]', 0, 'Waterproof nylon keeps rain out and is light, so it is best for a tent.', 'Tents laugh at rainstorms!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0004', 'sci-materials', 4, 'quest', 'An iron nail sinks but a big iron ship floats. What is the most important reason?', '["The ship''s shape traps air, making it light for its size","Iron ships are made of lighter iron","The sea pushes ships up more","Ships have engines"]', 0, 'The ship is hollow and full of air, so it is light for its size and floats.', 'Hollow ships float — solid nails sink!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0005', 'sci-materials', 4, 'quest', 'Two pupils test which material is most waterproof. One pours 50 ml of water, the other pours 100 ml. Why is this test unfair?', '["They used different amounts of water","They used different materials","They tested on different days","They used different cups"]', 0, 'A fair test keeps everything the same except the material. Different amounts of water make it unfair.', 'Same water, same test — or it''s not fair!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0006', 'sci-materials', 4, 'fresh', 'Which list shows only materials?', '["Wood, glass, metal","Wood, water, light","Air, water, wood","Light, sound, metal"]', 0, 'Wood, glass and metal are all materials. Air, water, light and sound are not.', 'Materials are the stuff things are made of!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0007', 'sci-materials', 4, 'fresh', 'Leather comes from animal skin. It is a…', '["natural material","man-made material","liquid","gas"]', 0, 'Leather comes from animals, so it is a natural material.', 'Leather jackets come from nature!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0008', 'sci-materials', 4, 'fresh', 'A rope for climbing must be strong AND flexible. Which material is best?', '["Nylon rope","Glass rod","Ceramic tile","Paper string"]', 0, 'Nylon rope is strong and bends without breaking.', 'Climbing ropes are strong and bendy!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0009', 'sci-materials', 4, 'fresh', 'A straw must bend without breaking. Which material is best?', '["Flexible plastic","Glass","Ceramic","Wood"]', 0, 'Flexible plastic bends without breaking.', 'Bendy straws are the best straws!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0010', 'sci-materials', 4, 'fresh', 'Which of these is waterproof?', '["Waxed paper","Tissue paper","Cotton wool","Newspaper"]', 0, 'Waxed paper has a wax layer that stops water soaking through.', 'Wax says ''no'' to water!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0011', 'sci-materials', 4, 'fresh', 'Which two materials are both absorbent?', '["Sponge and towel cloth","Plastic and glass","Metal and stone","Rubber and plastic"]', 0, 'Sponges and towel cloth both soak up water.', 'Sponges and towels — the thirsty pair!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0012', 'sci-materials', 4, 'fresh', 'Which material is best for a fish tank?', '["Clear glass","Wood","Cardboard","Metal"]', 0, 'Clear glass is transparent, so you can see the fish, and waterproof, so the water stays in.', 'Glass tanks let you watch the fish!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0013', 'sci-materials', 4, 'fresh', 'Which of these will sink in water?', '["A glass marble","A cork","A plastic bottle cap","A leaf"]', 0, 'A glass marble is heavy for its size, so it sinks. Cork, plastic caps and leaves float.', 'Marbles dive straight to the bottom!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0014', 'sci-materials', 4, 'fresh', 'A lunchbox must keep food dry and not break if dropped. Which two properties does it need?', '["Waterproof and strong","Transparent and absorbent","Flexible and absorbent","Light and see-through"]', 0, 'A lunchbox must keep water out and survive drops, so it needs to be waterproof and strong.', 'Lunchboxes are tough little guardians!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0015', 'sci-materials', 4, 'fresh', 'Sara tests three materials to see which is strongest. She hangs the same weight on each until it breaks. What is she changing, and what is she keeping the same?', '["Changing the material; keeping the weight the same","Changing the weight; keeping the material the same","Changing both","Changing nothing"]', 0, 'She changes only the material. The weight stays the same, so the test is fair.', 'Same weight, different material — fair test!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0016', 'sci-materials', 4, 'warm', 'Which material is both flexible and waterproof?', '["Rubber","Glass","Paper","Wood"]', 0, '', '', 'bank') on conflict (id) do nothing;
