insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0018', 'sci-materials', 4, 'warm', 'Which pair is transparent?', '["Clear glass and clean water","Wood and brick","Cloth and paper","Metal and stone"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0019', 'sci-materials', 4, 'warm', 'A cooking pot must not melt over fire. Which property matters most?', '["It must not melt easily in heat","It must be transparent","It must float","It must soak up water"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0020', 'sci-materials', 4, 'warm', 'Ceramics are made from clay that is baked hard. They are…', '["man-made materials","living things","liquids","gases"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0021', 'sci-materials', 4, 'warm', 'Which of these is the strongest material for a bridge?', '["Steel","Rubber","Paper","Cloth"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0022', 'sci-materials', 4, 'warm', 'Which of these will get wet through in the rain?', '["Cotton shirt","Plastic raincoat","Rubber boots","Umbrella"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0023', 'sci-materials', 4, 'warm', 'A life jacket helps you float because it is made of a material that is…', '["light and full of air","heavy and strong","made of metal","very thin"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0024', 'sci-materials', 4, 'retry', 'A paper towel soaks up more water than a plastic bag. What does this tell you?', '["Paper towel is more absorbent than plastic","Plastic is more absorbent than paper","Both are waterproof","Both are transparent"]', 0, 'Soaking up more water means the paper towel is more absorbent.', 'Paper towels win the soak-up race!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0025', 'sci-materials', 4, 'retry', 'Why can''t you use a wooden board as a window?', '["Wood is opaque and lets no light through","Wood is too strong","Wood is waterproof","Wood is flexible"]', 0, 'Windows must let light through. Wood is opaque, so it blocks the light.', 'Wooden windows would make dark rooms!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0026', 'sci-materials', 4, 'retry', 'A kite must be light and strong. Which material is best?', '["Light, strong fabric","Glass","Brick","Metal sheet"]', 0, 'A kite must be light to fly and strong to hold its shape.', 'Kites dance on the wind!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0027', 'sci-materials', 4, 'retry', 'Ben tests which cloth dries fastest. He puts one cloth in the sun and one in the shade. What is wrong with his test?', '["He changed two things — the cloth and the place","He used cloth","He tested in the daytime","He used water"]', 0, 'He changed the cloth AND the place, so he cannot tell which one made the difference.', 'One change at a time, Ben!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0028', 'sci-materials', 4, 'retry', 'Which of these is flexible?', '["A rubber band","A brick","A glass bottle","A ceramic mug"]', 0, 'A rubber band bends and stretches without breaking.', 'Rubber bands are stretchy stars!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-materials-p4-0029', 'sci-materials', 4, 'retry', 'Which material would you choose for a helmet?', '["Strong plastic","Paper","Cloth","Tissue"]', 0, 'A helmet must be strong to protect your head.', 'Helmets keep brave heads safe!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0001', 'sci-plants', 3, 'quest', 'Which of these is a living thing?', '["A puppy","A stone","A cup","A cloud"]', 0, 'A puppy can move, grow and eat, so it is a living thing.', 'Puppies are definitely alive — and very lively!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0002', 'sci-plants', 3, 'quest', 'A plant is a living thing because it can…', '["grow and make food","move from place to place","talk to people","sleep all day"]', 0, 'Plants grow and make their own food, so they are living things.', 'Plants grow quietly — but they grow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0003', 'sci-plants', 3, 'fresh', 'Which of these shows that something is living?', '["It grows bigger over time","It is colourful","It is heavy","It is cold"]', 0, 'Growing is a sign of life. Colour, weight and coldness are not.', 'Growing is life''s way of saying hello!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0004', 'sci-plants', 3, 'fresh', 'A robot moves and makes sounds. Is it a living thing?', '["No, it cannot grow or reproduce","Yes, because it moves","Yes, because it makes sounds","No, because it is small"]', 0, 'Moving is not enough. Living things grow, reproduce and need food and air.', 'Robots move, but they don''t grow — not alive!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0005', 'sci-plants', 3, 'retry', 'Which of these is NOT a living thing?', '["A bicycle","A fish","A tree","A bird"]', 0, 'A bicycle cannot grow, eat or reproduce, so it is not living.', 'Bicycles go fast, but they aren''t alive!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0001', 'sci-plants', 4, 'quest', 'A fire moves, gives off heat and grows bigger. Is it a living thing?', '["No, it does not grow, eat or reproduce","Yes, because it moves and grows","Yes, because it gives off heat","No, because it is hot"]', 0, 'Fire does not eat, reproduce or respond like a living thing. It is not alive.', 'Fire dances, but it isn''t alive!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0002', 'sci-plants', 4, 'quest', 'Which two things prove that a seed is alive?', '["It can grow into a plant and needs water and air","It is small and brown","It is hard and round","It comes from a plant"]', 0, 'A seed can grow and needs water and air, so it is alive.', 'Seeds sleep until it''s time to grow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0003', 'sci-plants', 4, 'fresh', 'A fallen leaf on the ground is brown and dry. Is it still a living thing?', '["No, it is dead and cannot grow","Yes, it is still a leaf","Yes, because it was green","No, because it is brown"]', 0, 'A fallen leaf cannot grow or make food any more, so it is no longer living.', 'Fallen leaves have finished their leafy lives!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0004', 'sci-plants', 4, 'fresh', 'Which of these can respond to changes around it?', '["A sunflower turning to face the sun","A stone rolling downhill","A cup falling off a table","A shadow moving across a wall"]', 0, 'Responding to light is a sign of life. Rolling, falling and shadows are not.', 'Sunflowers follow the sun — clever plants!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0005', 'sci-plants', 4, 'retry', 'A car moves, uses fuel and makes noise. Why is it not a living thing?', '["It cannot grow or reproduce","It is too big","It is made of metal","It moves too fast"]', 0, 'Living things grow and reproduce. A car cannot do either.', 'Cars zoom, but they never grow up!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0006', 'sci-plants', 3, 'quest', 'Which of these is a non-living thing?', '["A rock","A rabbit","A rose","A fish"]', 0, 'A rock cannot move by itself, grow or eat, so it is non-living.', 'Rocks just sit there — very non-living!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0007', 'sci-plants', 3, 'quest', 'Air and water are non-living, but living things need them to…', '["stay alive","grow taller only","make sounds","change colour"]', 0, 'Living things need air and water to stay alive.', 'Air and water are life''s helpers!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0008', 'sci-plants', 3, 'fresh', 'Which group has only living things?', '["Dog, tree, fish","Dog, rock, fish","Tree, stone, bird","Fish, cloud, rose"]', 0, 'Dogs, trees and fish are all living. Rocks, stones and clouds are not.', 'Dogs, trees, fish — all alive!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0009', 'sci-plants', 3, 'fresh', 'A boy puts a stone and a snail in a box. The next day, the snail has moved but the stone has not. What does this show?', '["The snail is living and the stone is not","The stone is living","Both are living","Both are non-living"]', 0, 'Moving by itself is a sign of life. The snail moved, the stone did not.', 'Snails move — stones stay put!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0010', 'sci-plants', 3, 'retry', 'Which of these is alive?', '["A mushroom","A plastic bag","A spoon","A book"]', 0, 'A mushroom is a fungus, and fungi are living things.', 'Mushrooms are alive — quietly growing!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0006', 'sci-plants', 4, 'quest', 'A scientist finds a tiny thing in pond water that moves and eats. What can she say about it?', '["It is a living thing","It is a stone","It is a cloud","It is a shadow"]', 0, 'Moving and eating are signs of life, so it is a living thing.', 'Tiny pond creatures are alive and busy!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0007', 'sci-plants', 4, 'quest', 'Which of these is non-living but was once part of a living thing?', '["A wooden chair","A puppy","A rose","A goldfish"]', 0, 'Wood comes from a tree, which was living, but the chair itself is not alive.', 'Wooden chairs were trees once!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0008', 'sci-plants', 4, 'fresh', 'Water is not alive, yet fish need it. Which sentence is correct?', '["Water is non-living, but living things need it","Water is a living thing","Fish do not need water","Only plants need water"]', 0, 'Water is non-living, but fish need it to live.', 'Water isn''t alive — but life needs it!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0009', 'sci-plants', 4, 'fresh', 'A seed is small and hard and does not move. How do you know it is alive?', '["It can grow into a plant when given water and warmth","It is brown","It is round","It comes from a tree"]', 0, 'A seed grows into a plant, which shows it is alive.', 'Seeds are sleeping plants!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0010', 'sci-plants', 4, 'retry', 'Which pair shows one living and one non-living thing?', '["Butterfly and kite","Butterfly and bee","Kite and stone","Bee and butterfly"]', 0, 'A butterfly is living, a kite is not. The other pairs are both living or both non-living.', 'Butterflies fly — kites fly too, but only one is alive!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0011', 'sci-plants', 3, 'quest', 'What do ALL living things need to stay alive?', '["Air, food and water","Sunlight, soil and rain","Toys, books and games","Shoes, clothes and hats"]', 0, 'All living things need air, food and water.', 'Air, food, water — life''s big three!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0012', 'sci-plants', 3, 'fresh', 'A fish is taken out of water. What will happen?', '["It cannot breathe and will die","It will grow legs","It will fly away","It will turn into a frog"]', 0, 'Fish need water to breathe, so a fish out of water cannot live.', 'Fish need water like we need air!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0013', 'sci-plants', 3, 'retry', 'Plants need sunlight, air, water and ___ to grow well.', '["nutrients from the soil","toys","music","shoes"]', 0, 'Plants need nutrients from the soil as well as sunlight, air and water.', 'Soil food helps plants grow big and strong!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0011', 'sci-plants', 4, 'quest', 'A plant in a dark cupboard has water and air, but no sunlight. What will happen?', '["It will turn yellow and die","It will grow faster","It will make more flowers","It will turn into a tree"]', 0, 'Plants need sunlight to make food. Without it, the plant cannot live.', 'No sun, no food — poor plant!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0012', 'sci-plants', 4, 'fresh', 'Animals need food for energy and to grow. What do plants use to make their food?', '["Sunlight, water and air","Meat and fish","Milk and bread","Soil and stones"]', 0, 'Plants make food using sunlight, water and air.', 'Plants cook their own food with sunlight!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0013', 'sci-plants', 4, 'retry', 'Why do living things in a desert need water most of all?', '["Without water they cannot live","Water makes them colourful","Water helps them fly","Water makes them bigger"]', 0, 'All living things need water to stay alive.', 'Desert life is thirsty work!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0014', 'sci-plants', 3, 'quest', 'Why does a flower need bees to visit it?', '["To carry pollen so seeds can form","To eat the petals","To make the flower smell nice","To keep the flower warm"]', 0, 'Bees carry pollen between flowers, and that helps seeds form.', 'Bees are flower messengers!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0015', 'sci-plants', 3, 'fresh', 'What comes first in a plant''s life cycle?', '["A seed","A flower","A fruit","A seedling"]', 0, 'A plant''s life cycle starts with a seed.', 'Every big tree starts as a tiny seed!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0016', 'sci-plants', 3, 'retry', 'What is the job of a flower''s nectar?', '["To attract insects that carry pollen","To make the flower smell nice for people","To keep the flower warm","To make seeds"]', 0, 'Nectar attracts insects, and the insects carry pollen.', 'Nectar is a sweet invitation for bees!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0014', 'sci-plants', 4, 'quest', 'A farmer removes all the flowers from his plants. What will happen?', '["The plants will make no fruits or seeds","The plants will grow taller","The plants will make more leaves","Nothing will change"]', 0, 'Flowers make seeds and fruits. Without flowers, there will be no fruits or seeds.', 'No flowers, no fruits — oh no!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0015', 'sci-plants', 4, 'fresh', 'Why must a seed fall far from its parent plant to grow well?', '["So it does not fight the parent for sunlight, water and space","So it can fly","So animals can eat it","So it stays dry"]', 0, 'Young plants need their own sunlight, water and space to grow.', 'Seeds need their own room to grow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p4-0016', 'sci-plants', 4, 'retry', 'A plant''s life cycle goes seed → seedling → adult plant → flower → fruit → seed. Why does it go in a circle?', '["Because the seeds grow into new plants and the cycle starts again","Because plants like circles","Because the sun moves in a circle","Because flowers are round"]', 0, 'The seeds from the fruit grow into new plants, so the cycle repeats.', 'Life cycles go round and round!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0017', 'sci-plants', 3, 'quest', 'To test if seeds need water to grow, what should you do?', '["Give water to one set of seeds and none to the other","Give water to all the seeds","Give no water to any seeds","Water the seeds at night only"]', 0, 'Change only the water. Give one set water and the other none, and keep everything else the same.', 'Water or no water — the seeds will tell you!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0018', 'sci-plants', 3, 'quest', 'Ali puts one plant in sunlight and one in a dark cupboard. What is he testing?', '["Whether plants need sunlight","Whether plants need water","Whether plants need soil","Whether plants need air"]', 0, 'He changed only the light, so he is testing if plants need sunlight.', 'Sunlight or darkness — the plants will show you!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0019', 'sci-plants', 3, 'fresh', 'In a fair test about seeds and water, what must stay the same?', '["The light, warmth and type of seeds","The amount of water","The number of seeds that grow","The colour of the pots"]', 0, 'Keep light, warmth and seed type the same. Only the water changes.', 'Same seeds, same light — only water changes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0020', 'sci-plants', 3, 'fresh', 'Mei wants to find out if plants need air. What should she change?', '["The air around the plant","The colour of the pot","The size of the leaves","The time of day"]', 0, 'To test air, change only the air around the plant.', 'Air is invisible, but plants need it!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-plants-p3-0021', 'sci-plants', 3, 'retry', 'Why do we test only one thing at a time in an experiment?', '["So we know what caused the change","So the test is faster","So the plants grow bigger","So we use less water"]', 0, 'If you change two things, you cannot tell which one caused the change.', 'One change at a time — science detectives know!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0001', 'sci-frog', 3, 'quest', 'The graph shows a frog''s egg stage lasts 7 days, the tadpole stage lasts 42 days and the froglet stage lasts 14 days. How many days does it take from egg to adult frog?', '["63 days","49 days","56 days","70 days"]', 0, '7 + 42 + 14 = 63 days.', '63 days from egg to hopping frog!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0002', 'sci-frog', 3, 'quest', 'The graph shows a butterfly''s egg lasts 5 days, the caterpillar lasts 20 days and the pupa lasts 10 days. How long is the whole life cycle?', '["35 days","25 days","30 days","40 days"]', 0, '5 + 20 + 10 = 35 days.', '35 days from egg to butterfly!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0003', 'sci-frog', 3, 'fresh', 'The graph shows the tadpole stage lasts 42 days and the froglet stage lasts 14 days. How many more days is the tadpole stage?', '["28 days","14 days","42 days","56 days"]', 0, '42 − 14 = 28 days longer.', 'Tadpoles take their time — 28 extra days!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0004', 'sci-frog', 3, 'fresh', 'A bar chart shows how long each stage of a mosquito''s life lasts: egg 2 days, larva 7 days, pupa 2 days. How many days until the adult mosquito appears?', '["11 days","9 days","7 days","13 days"]', 0, '2 + 7 + 2 = 11 days.', '11 days and out comes a mosquito!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0005', 'sci-frog', 3, 'retry', 'The graph shows a chicken''s egg stage lasts 21 days. How many weeks is that?', '["3 weeks","2 weeks","4 weeks","1 week"]', 0, '21 days ÷ 7 days = 3 weeks.', 'Three weeks of waiting for a chick!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0001', 'sci-frog', 4, 'quest', 'A graph shows a frog''s life cycle: egg 7 days, tadpole 42 days, froglet 14 days. A butterfly''s life cycle: egg 5 days, caterpillar 20 days, pupa 10 days. Which life cycle is longer, and by how many days?', '["The frog''s, by 28 days","The butterfly''s, by 28 days","The frog''s, by 14 days","They are the same"]', 0, 'Frog: 63 days. Butterfly: 35 days. 63 − 35 = 28 days longer.', 'Frogs take their time — 28 days more!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0002', 'sci-frog', 4, 'quest', 'The graph shows a mosquito''s larva stage lasts 7 days. If the eggs hatch on Monday, on which day does the pupa stage start?', '["The next Monday","Wednesday","Friday","Sunday"]', 0, '7 days after Monday is the next Monday.', 'A week of wriggling, then pupating!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0003', 'sci-frog', 4, 'fresh', 'A bar chart shows: tadpole 42 days, froglet 14 days. What fraction of the time from tadpole to adult is spent as a tadpole?', '["42 out of 56 days","14 out of 56 days","42 out of 14 days","14 out of 42 days"]', 0, 'Tadpole to adult is 42 + 14 = 56 days. The tadpole stage is 42 of those days.', 'Tadpoles hog most of the timeline!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0004', 'sci-frog', 4, 'fresh', 'The graph shows a hen''s egg hatches after 21 days and a duck''s egg after 28 days. How many days longer does the duck''s egg take?', '["7 days","14 days","21 days","28 days"]', 0, '28 − 21 = 7 days longer.', 'Ducklings take a week longer to hatch!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0005', 'sci-frog', 4, 'retry', 'A scientist records that a tadpole grows legs after 42 days. If the eggs were laid on 1 March, on about which date does the tadpole grow legs?', '["12 April","15 March","1 April","30 March"]', 0, '42 days after 1 March is about 12 April.', 'Six weeks of swimming, then legs!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0006', 'sci-frog', 3, 'quest', 'Which animal has three stages in its life cycle?', '["Chicken","Frog","Butterfly","Mosquito"]', 0, 'A chicken has three stages: egg, chick, hen. Frogs, butterflies and mosquitoes have four.', 'Chickens keep it simple — three stages!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0007', 'sci-frog', 3, 'fresh', 'What are the three stages of a grasshopper''s life cycle?', '["Egg, nymph, adult","Egg, tadpole, frog","Egg, caterpillar, pupa","Egg, larva, pupa"]', 0, 'A grasshopper goes egg → nymph → adult.', 'Nymphs look like mini grasshoppers!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0008', 'sci-frog', 3, 'retry', 'A chick looks like a small hen. What does this tell you?', '["The chick is the young of the hen and they look alike","The chick is a different animal","The chick will become a frog","The chick has four stages"]', 0, 'The young of a chicken looks like its adult, so they are the same kind of animal.', 'Chicks are mini hens!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0006', 'sci-frog', 4, 'quest', 'A grasshopper nymph looks like a small adult but has no wings. What happens as it grows?', '["It grows wings and becomes an adult","It grows a tail","It becomes a tadpole","It lays eggs at once"]', 0, 'The nymph grows bigger and grows wings, then becomes an adult grasshopper.', 'Nymphs grow up — wings included!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0007', 'sci-frog', 4, 'fresh', 'Which two animals both have three stages in their life cycles?', '["Chicken and grasshopper","Frog and butterfly","Mosquito and frog","Butterfly and chicken"]', 0, 'Chickens and grasshoppers both have three stages.', 'Three stages, two animals — neat!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0008', 'sci-frog', 4, 'retry', 'Why does a grasshopper''s life cycle have fewer stages than a frog''s?', '["The nymph already looks like the adult, so it does not need a tadpole stage","Grasshoppers grow faster","Frogs are bigger","Grasshoppers live in water"]', 0, 'A frog changes shape completely, but a nymph already looks like an adult grasshopper.', 'No big makeover needed for grasshoppers!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0009', 'sci-frog', 3, 'quest', 'In a life cycle diagram, an arrow points from the egg to the tadpole. What does the arrow show?', '["The egg grows into a tadpole","The egg eats the tadpole","The tadpole lays the egg","The egg swims away"]', 0, 'Arrows in a life cycle show what grows into what.', 'Follow the arrows — they tell the story!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0010', 'sci-frog', 3, 'fresh', 'A diagram shows: egg → caterpillar → pupa → butterfly. What comes after the pupa?', '["A butterfly","An egg","A caterpillar","A tadpole"]', 0, 'The arrow after the pupa points to the butterfly.', 'Out of the pupa comes a butterfly!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0011', 'sci-frog', 3, 'retry', 'In a frog''s life cycle diagram, the adult frog points back to the egg. What does this mean?', '["The adult lays eggs and the cycle starts again","The frog eats its eggs","The frog turns back into an egg","The eggs hatch at once"]', 0, 'The cycle repeats — adults lay eggs and new frogs grow.', 'Round and round the froggy cycle goes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0009', 'sci-frog', 4, 'quest', 'A diagram shows a butterfly''s life cycle with the pupa stage missing. Which stage is missing between the caterpillar and the butterfly?', '["The pupa","The egg","The larva","The adult"]', 0, 'A butterfly''s cycle is egg → caterpillar → pupa → butterfly.', 'Don''t skip the pupa — it''s the magic stage!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0010', 'sci-frog', 4, 'fresh', 'In a mosquito''s life cycle diagram, the larva lives in water but the adult flies in the air. What does the diagram tell you?', '["The mosquito lives in water and in air at different stages","The mosquito lives only in water","The mosquito lives only in air","The larva can fly"]', 0, 'Different stages live in different places.', 'Water baby, air adult — two homes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p4-0011', 'sci-frog', 4, 'retry', 'A life cycle diagram of a plant shows a seed growing into a seedling. If the seedling is removed, what happens to the cycle?', '["The cycle stops — no adult plant, no new seeds","The cycle goes faster","The seed grows again","Nothing changes"]', 0, 'Without a seedling, there is no adult plant and no new seeds, so the cycle stops.', 'No seedling, no cycle — every stage matters!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0012', 'sci-frog', 3, 'quest', 'Where do mosquitoes lay their eggs?', '["In still water","On dry land","On tree leaves","In the air"]', 0, 'Mosquitoes lay their eggs in still water.', 'Still water is a mosquito nursery!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0013', 'sci-frog', 3, 'quest', 'How can we stop mosquitoes from breeding at home?', '["Remove still water from pots and trays","Leave water standing for a week","Keep windows open all day","Water the plants more"]', 0, 'Without still water, mosquitoes have nowhere to lay eggs.', 'No still water, no baby mosquitoes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0014', 'sci-frog', 3, 'fresh', 'A mosquito larva lives in water and is called a…', '["wriggler","tadpole","caterpillar","nymph"]', 0, 'Mosquito larvae are called wrigglers because they wriggle in the water.', 'Wrigglers wriggle — that''s their name!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0015', 'sci-frog', 3, 'fresh', 'What are the four stages of a mosquito''s life cycle?', '["Egg, larva, pupa, adult","Egg, tadpole, froglet, adult","Egg, chick, hen, adult","Egg, nymph, adult, egg"]', 0, 'A mosquito goes egg → larva → pupa → adult.', 'Four stages to a buzzy mosquito!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-frog-p3-0016', 'sci-frog', 3, 'retry', 'Why should we cover water containers at home?', '["So mosquitoes cannot lay eggs in them","So the water stays cold","So the water looks clean","So fish can live in them"]', 0, 'Covered water keeps mosquitoes out, so they cannot lay eggs.', 'Lids keep mosquitoes out!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0001', 'sci-magnet', 3, 'quest', 'A steel spoon is attracted to a magnet. Is the spoon a magnet?', '["No, it is a magnetic material, not a magnet","Yes, it is a magnet","No, it is made of wood","Yes, it is an electromagnet"]', 0, 'The spoon is magnetic — it is attracted to a magnet — but it is not a magnet itself.', 'Magnetic is not the same as being a magnet!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0002', 'sci-magnet', 3, 'fresh', 'Which of these is a magnet?', '["A bar magnet","A steel nail","An iron key","A paperclip"]', 0, 'A bar magnet is a magnet. A nail, key and paperclip are magnetic materials.', 'Bar magnets are the real magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0003', 'sci-magnet', 3, 'retry', 'Which of these is magnetic but NOT a magnet?', '["A steel paperclip","A bar magnet","A horseshoe magnet","A compass needle"]', 0, 'A paperclip is attracted to magnets, but it is not a magnet itself.', 'Paperclips stick — but they aren''t magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0001', 'sci-magnet', 4, 'quest', 'A magnet attracts a paperclip, but the paperclip does not attract a pin. What does this show?', '["The paperclip is magnetic but not a magnet","The paperclip is a magnet","The pin is a magnet","Magnets do not attract paperclips"]', 0, 'Only magnets attract other things. The paperclip is magnetic, not a magnet.', 'Only real magnets do the attracting!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0002', 'sci-magnet', 4, 'fresh', 'Which of these is a magnet and which is a magnetic material? A fridge magnet and a steel spoon.', '["The fridge magnet is a magnet; the spoon is a magnetic material","Both are magnets","Both are magnetic materials","The spoon is a magnet; the fridge magnet is not"]', 0, 'The fridge magnet attracts things. The spoon is attracted, but is not a magnet.', 'Magnets attract — materials get attracted!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0003', 'sci-magnet', 4, 'retry', 'Mei says a steel nail is a magnet because a magnet picks it up. Is she right?', '["No, the nail is magnetic, not a magnet","Yes, she is right","No, the nail is made of wood","Yes, all steel things are magnets"]', 0, 'Being picked up shows the nail is magnetic. A magnet is the thing that does the picking up.', 'Picked up is not the same as picking up!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0004', 'sci-magnet', 3, 'quest', 'How can you test which magnet is stronger?', '["Count how many paperclips each magnet can pick up","See which magnet is bigger","See which magnet is heavier","See which magnet is shinier"]', 0, 'The magnet that picks up more paperclips is stronger.', 'More paperclips, stronger magnet!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0005', 'sci-magnet', 3, 'fresh', 'A magnet picks up 10 paperclips. Another picks up 5. Which is stronger?', '["The one that picks up 10","The one that picks up 5","They are the same","You cannot tell"]', 0, 'More paperclips means a stronger pull.', 'Ten beats five — stronger magnet wins!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0006', 'sci-magnet', 3, 'retry', 'To test magnet strength fairly, what must you use for both magnets?', '["The same kind of paperclips","Different paperclips","Bigger paperclips for one","Smaller paperclips for one"]', 0, 'Use the same paperclips so the test is fair.', 'Same clips, fair test!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0004', 'sci-magnet', 4, 'quest', 'Mei tests two magnets. She uses big paperclips for one and small pins for the other. Is this a fair test?', '["No, she changed the objects too","Yes, it is fair","No, she used magnets","Yes, pins and clips are the same"]', 0, 'She changed the objects as well as the magnet, so the test is not fair.', 'Fair tests change one thing only!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0005', 'sci-magnet', 4, 'fresh', 'Which is the best way to compare the strength of two magnets?', '["Pick up the same paperclips with each magnet and count them","Drop both magnets and see which breaks","Weigh both magnets","Look at the colours"]', 0, 'Counting the same paperclips each magnet picks up is a fair test.', 'Count the clips — the numbers don''t lie!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0006', 'sci-magnet', 4, 'retry', 'A magnet picks up 12 pins. After it is dropped many times, it picks up only 6 pins. What happened?', '["It became weaker","It became stronger","It became bigger","It became a different magnet"]', 0, 'Dropping a magnet many times can make it weaker.', 'Dropped magnets lose their superpower!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0007', 'sci-magnet', 3, 'quest', 'Which of these can be made into a magnet?', '["A steel nail","A wooden stick","A plastic ruler","A copper coin"]', 0, 'Steel is magnetic, so a steel nail can be made into a magnet.', 'Steel nails can become magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0008', 'sci-magnet', 3, 'fresh', 'Can a copper coin be made into a magnet?', '["No, copper is not magnetic","Yes, easily","No, copper is too small","Yes, with water"]', 0, 'Copper is not magnetic, so it cannot be made into a magnet.', 'Copper coins say no to magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0009', 'sci-magnet', 3, 'retry', 'Which of these cannot be made into a magnet?', '["A wooden spoon","An iron nail","A steel paperclip","A nickel coin"]', 0, 'Wood is not magnetic, so a wooden spoon cannot become a magnet.', 'Wooden spoons will never be magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0007', 'sci-magnet', 4, 'quest', 'Why can a steel nail be made into a magnet but a wooden stick cannot?', '["Steel is magnetic and wood is not","Steel is heavier","Wood is longer","Steel is shinier"]', 0, 'Only magnetic materials can be made into magnets.', 'Magnetic in, magnetic out!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0008', 'sci-magnet', 4, 'fresh', 'Which pair of objects can BOTH be made into magnets?', '["Iron nail and steel paperclip","Wooden ruler and plastic pen","Copper coin and glass marble","Rubber band and paperclip"]', 0, 'Iron and steel are both magnetic, so both can be made into magnets.', 'Iron and steel — the magnetic pair!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p4-0009', 'sci-magnet', 4, 'retry', 'A pupil tries to make a magnet from a plastic ruler by stroking it with a magnet. What will happen?', '["Nothing — plastic is not magnetic","The ruler becomes a strong magnet","The ruler becomes an electromagnet","The ruler breaks"]', 0, 'Plastic is not magnetic, so stroking it does nothing.', 'Plastic rulers just don''t do magnets!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0010', 'sci-magnet', 3, 'quest', 'Two magnets are put together and they push apart. What do you know about the poles that are touching?', '["They are the same — both north or both south","They are different — one north, one south","They are not poles at all","They are broken"]', 0, 'Like poles push apart, so the touching poles must be the same.', 'Same poles say ''go away''!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0011', 'sci-magnet', 3, 'quest', 'A magnet''s north pole is near another magnet''s pole and they pull together. What is the other pole?', '["South","North","East","West"]', 0, 'Opposite poles pull together, so the other pole must be south.', 'North loves south — opposites attract!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0012', 'sci-magnet', 3, 'fresh', 'Magnet A has its north pole facing magnet B. They push apart. What is the pole of B that faces A?', '["North","South","East","West"]', 0, 'They push apart, so the poles are the same — B''s pole must be north too.', 'North meets north — push!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0013', 'sci-magnet', 3, 'fresh', 'You have two magnets. One end of the first magnet attracts one end of the second magnet. What can you say?', '["The two ends are opposite poles","The two ends are the same pole","The magnets are broken","The magnets are not real"]', 0, 'Attraction means opposite poles.', 'Opposites attract — magnet rule number one!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0014', 'sci-magnet', 3, 'retry', 'A pupil labels the poles of a magnet wrongly. How can she check which end is really north?', '["See which end points north when the magnet hangs freely","Paint the magnet red","Drop the magnet","Put the magnet in water"]', 0, 'A freely hanging magnet turns so its north pole points north.', 'A hanging magnet is a compass in disguise!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0015', 'sci-magnet', 3, 'quest', 'Ali strokes a nail with a bar magnet 20 times in the same direction. What happens to the nail?', '["It becomes a temporary magnet","It becomes a permanent magnet","It melts","It breaks"]', 0, 'Stroking a steel nail in one direction makes it a temporary magnet.', 'Stroke, stroke — now the nail is a magnet!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0016', 'sci-magnet', 3, 'quest', 'What must you do to make a steel nail into a temporary magnet?', '["Stroke it with a magnet in one direction many times","Hit it with a hammer","Put it in water","Paint it red"]', 0, 'Stroking in one direction lines up the tiny magnets inside the nail.', 'One direction, many times — that''s the trick!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0017', 'sci-magnet', 3, 'fresh', 'A nail stroked with a magnet can pick up paperclips. What kind of magnet is it?', '["A temporary magnet","A permanent magnet","An electromagnet","A compass"]', 0, 'The nail is a temporary magnet — it will lose its magnetism over time.', 'Temporary magnets don''t last forever!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0018', 'sci-magnet', 3, 'fresh', 'What happens if you stroke a nail in different directions each time?', '["It will not become a magnet","It becomes a stronger magnet","It becomes an electromagnet","It turns into iron"]', 0, 'Stroking in different directions does not line up the tiny magnets inside.', 'Same direction every time — no zig-zagging!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0019', 'sci-magnet', 3, 'retry', 'Why is a stroked nail called a temporary magnet?', '["It loses its magnetism after some time","It is very strong","It lasts forever","It can never pick up paperclips"]', 0, 'A temporary magnet loses its magnetism over time.', 'Temporary means ''not forever''!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0020', 'sci-magnet', 3, 'quest', 'Mei wraps wire around a nail and connects it to a battery. What has she made?', '["An electromagnet","A compass","A permanent magnet","A light bulb"]', 0, 'Wire around iron plus a battery makes an electromagnet.', 'Wire plus battery — magnet magic!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0021', 'sci-magnet', 3, 'quest', 'How do you switch off an electromagnet?', '["Disconnect the battery","Drop it in water","Paint it blue","Hit it with a hammer"]', 0, 'An electromagnet only works while the battery is connected.', 'No battery, no magnet — off!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0022', 'sci-magnet', 3, 'fresh', 'Mei wants to make an electromagnet. Which set of things does she need?', '["Wire, an iron nail and a battery","Wood, water and paper","A magnet and a ruler","Glass and plastic"]', 0, 'An electromagnet needs wire coiled around iron and a battery.', 'Three things make an electromagnet!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0023', 'sci-magnet', 3, 'fresh', 'An electromagnet can pick up pins when the battery is connected. What happens when the battery is taken away?', '["It drops the pins","It picks up more pins","It becomes stronger","It turns into a compass"]', 0, 'Without the battery, the electromagnet stops working and drops the pins.', 'Battery off, pins drop!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('sci-magnet-p3-0024', 'sci-magnet', 3, 'retry', 'Ali''s electromagnet is too weak to pick up pins. What should he do?', '["Wrap more coils of wire around the nail","Use less wire","Take away the battery","Use a plastic nail"]', 0, 'More coils of wire make the electromagnet stronger.', 'More coils, more power!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0001', 'chi-char', 3, 'quest', '小明___天要去学校参加运动会。', '["名","鸣","明","命"]', 2, '明天 means tomorrow — 日 (sun) + 月 (moon) = 明 (bright).', '明 is bright like the sun and moon!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0002', 'chi-char', 3, 'quest', '今天的太___很热，大家都躲在树下乘凉。', '["羊","阳","洋","杨"]', 1, '太阳 means the sun — 阳 has the 日 (sun) part.', '太阳公公笑眯眯！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0003', 'chi-char', 3, 'quest', '小鸟在天空中自由地___翔。', '["非","菲","妃","飞"]', 3, '飞翔 means to fly — 飞 looks like a bird flying.', '飞呀飞，飞上蓝天！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0004', 'chi-char', 3, 'quest', '妈妈___我去公园玩滑梯。', '["带","戴","代","待"]', 0, '带 means to take someone along — 带 has 巾, like a scarf you carry.', '妈妈带我去玩，我最开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0005', 'chi-char', 3, 'quest', '小华有一___可爱的小狗，它的名字叫小白。', '["支","纸","只","织"]', 2, '一只小狗 — 只 is the measure word for small animals.', '汪汪！一只小狗跑来了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0006', 'chi-char', 3, 'fresh', '请你认___听老师讲课。', '["直","具","真","且"]', 2, '认真 means serious and focused — 真 is the real, true one.', '认真听讲，知识跑进脑子里！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0007', 'chi-char', 3, 'fresh', '我___在家里看书。', '["在","再","载","栽"]', 0, '在 means at / in a place — 我在家里，我在家。', '我在家里看书，真舒服！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0008', 'chi-char', 3, 'fresh', '小丽___了三遍，才把这篇课文背下来。', '["渎","读","犊","续"]', 1, '读 means to read aloud — 读 has 言 (words) on the left.', '读三遍，背得牢牢的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0009', 'chi-char', 3, 'fresh', '中秋节的晚上，月亮又大又___。', '["园","元","原","圆"]', 3, '又大又圆 — 圆 means round, with 囗 (an enclosure) around 员。', '月亮圆圆，像一个月饼！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0010', 'chi-char', 3, 'fresh', '我们要爱护___园里的花草树木。', '["较","校","咬","胶"]', 1, '校园 means the school grounds — 校 has 木 (wood) on the left.', '校园里的花草真美！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0011', 'chi-char', 3, 'fresh', '小明___跑步比赛得了第一名。', '["常","张","长","帐"]', 2, '长跑 means long-distance running — 长 means long.', '长跑第一名，真厉害！', 'bank') on conflict (id) do nothing;
