insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0027', 'chi-char', 3, 'retry', '小明每天早上都___牙洗脸。', '["涮","刺","刷","唰"]', 2, '刷牙 means to brush your teeth — 刷 has 尸 and 巾.', '刷刷牙，牙齿白白的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0028', 'chi-char', 3, 'retry', '我们要把垃圾扔进垃圾___里。', '["通","桶","痛","同"]', 1, '垃圾桶 means a rubbish bin — 桶 is the bucket word, with 木 (wood).', '垃圾进桶，环境干净！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p3-0029', 'chi-char', 3, 'retry', '冬天到了，小动物们都去___眠了。', '["终","东","冻","冬"]', 3, '冬眠 means to hibernate in winter — 冬 is winter.', '小动物冬眠了，春天再见！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0001', 'chi-char', 4, 'quest', '他___经读过这本书了，所以讲得很熟练。', '["己","巳","已","以"]', 2, '已经 means already — 已 is the finished one; 己 means oneself, 巳 is the snake sign.', '已经 — done and dusted!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0002', 'chi-char', 4, 'quest', '我们要学会___别字形相近的字。', '["辨","辩","辫","瓣"]', 0, '辨别 means to tell apart — 辨 has 辛 (hard work) in the middle.', '辨别清楚，不再写错！', 'bank') on conflict (id) do nothing;
