insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0022', 'chi-char', 4, 'warm', '春天到了，桃花开了，柳树也___了。', '["绿","录","碌","氯"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0023', 'chi-char', 4, 'warm', '小明___在写作业，突然电话响了。', '["政","证","正","症"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0024', 'chi-char', 4, 'retry', '我们要做一个___实的好孩子。', '["城","盛","诚","成"]', 2, '诚实 means honest — 诚 has 言 (words) on the left: true words.', '诚实的好孩子，人人喜欢！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0025', 'chi-char', 4, 'retry', '小华___真地对妈妈说：“对不起，我错了。”', '["认","忍","纫","韧"]', 0, '认真 means serious and sincere — 认 has 言 (words) on the left.', '认错的孩子真勇敢！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0026', 'chi-char', 4, 'retry', '天___了，路灯都亮了起来。', '["墨","默","里","黑"]', 3, '天黑了 means it got dark — 黑 means black.', '天黑了，路灯亮了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0027', 'chi-char', 4, 'retry', '小猫的毛很柔软，___起来很舒服。', '["模","摸","漠","膜"]', 1, '摸 means to touch with your hand — 摸 has 扌(hand) on the left.', '摸摸小猫，软软的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0028', 'chi-char', 4, 'retry', '我们___在图书馆里要保持安静。', '["智","蜘","知","织"]', 2, '知道 means to know — 知 has 矢 (arrow) on top.', '知道啦，安安静静！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-char-p4-0029', 'chi-char', 4, 'retry', '小明___了点头，表示他同意了。', '["点","占","战","店"]', 0, '点了点头 means to nod — 点 is the little dot that nods.', '点点头，就是同意！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0001', 'chi-picword', 3, 'quest', '图上画着一只小猫，它跑得很快，前面有一只蝴蝶在飞。哪个词语最合适？', '["睡觉","追逐","游泳","吃饭"]', 1, '追逐 means to chase — the cat is running after the butterfly!', '小猫追呀追，蝴蝶飞呀飞！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0002', 'chi-picword', 3, 'quest', '图上画着一个小男孩，他举着一把东西，雨点落在上面。哪个词语最合适？', '["晴天","晒太阳","打伞","堆雪人"]', 2, '打伞 means to hold an umbrella — it is raining in the picture!', '雨天打伞，干干净净！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0003', 'chi-picword', 3, 'quest', '图上画着一棵大树，树上挂满了红红的果子。哪个词语最合适？', '["结果","开花","落叶","发芽"]', 0, '结果 means to bear fruit — the red fruits are ripe on the tree!', '红苹果，甜又香！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0004', 'chi-picword', 3, 'quest', '图上画着小明坐在书桌前，眼睛盯着书本，一动不动。哪个词语最合适？', '["马虎","着急","伤心","认真"]', 3, '认真 means serious and focused — 小明 is reading carefully!', '认真读书，越读越聪明！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0005', 'chi-picword', 3, 'quest', '图上画着一只小鸟，它张开翅膀，在蓝天白云之间。哪个词语最合适？', '["游泳","飞翔","爬行","跳跃"]', 1, '飞翔 means to fly — the bird is flying in the sky!', '小鸟飞翔，自由自在！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0006', 'chi-picword', 3, 'fresh', '图上画着小明把地上的纸屑捡起来，扔进垃圾桶。哪个词语最合适？', '["乱扔垃圾","爱护环境","大声说话","浪费时间"]', 1, '爱护环境 means to care for our surroundings — 小明 keeps the place clean!', '爱护环境，人人有责！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0007', 'chi-picword', 3, 'fresh', '图上画着一群小鸭子跟着鸭妈妈，排成一行走路。哪个词语最合适？', '["排队行走","东倒西歪","横冲直撞","各自乱跑"]', 0, '排队行走 means to walk in a line — the ducklings follow mum one by one!', '小鸭子排队走，真可爱！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0008', 'chi-picword', 3, 'fresh', '图上画着小华跌倒了，小明伸出手把他扶起来。哪个词语最合适？', '["互相争吵","互不理睬","互相帮助","互相嘲笑"]', 2, '互相帮助 means to help each other — 小明 helps 小华 up!', '好朋友，互相帮助！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0009', 'chi-picword', 3, 'fresh', '图上画着夜晚的天空挂着一个又大又圆的东西，亮亮的。哪个词语最合适？', '["太阳很大","星星很多","乌云很多","月亮很圆"]', 3, '月亮很圆 means the moon is round and big — that bright round thing is the moon!', '月亮圆圆，像一个月饼！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0010', 'chi-picword', 3, 'fresh', '图上画着小朋友们在操场上跑步，一个比一个快。哪个词语最合适？', '["你追我赶","慢慢吞吞","东张西望","垂头丧气"]', 0, '你追我赶 means chasing each other to be first — they are racing!', '跑步比赛，加油加油！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0011', 'chi-picword', 3, 'fresh', '图上画着一棵小树苗，旁边放着水壶和铲子。哪个词语最合适？', '["砍树","摘果","种树","赏花"]', 2, '种树 means to plant a tree — there is a young tree, a watering can and a spade!', '小树苗，快快长大！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0012', 'chi-picword', 3, 'fresh', '图上画着小红把自己的铅笔借给了同桌。哪个词语最合适？', '["自私自利","乐于助人","斤斤计较","袖手旁观"]', 1, '乐于助人 means glad to help others — 小红 shares her pencil!', '帮助别人，自己也开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0013', 'chi-picword', 3, 'fresh', '图上画着冬天到了，小朋友们穿着厚厚的衣服，在雪地里做了一个白白胖胖的东西。哪个词语最合适？', '["游泳","种花","放风筝","堆雪人"]', 3, '堆雪人 means to build a snowman — the white fat thing is a snowman!', '雪人雪人，圆圆胖胖！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0014', 'chi-picword', 3, 'fresh', '图上画着小鸟妈妈叼着一条小虫子，送到张着嘴的小鸟嘴边。哪个词语最合适？', '["洗澡","睡觉","喂食","飞翔"]', 2, '喂食 means to feed — mum bird is giving the baby bird a worm!', '小鸟吃得香香的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0015', 'chi-picword', 3, 'fresh', '图上画着小朋友们坐在座位上，一动不动地听老师讲故事。哪个词语最合适？', '["安静听讲","大声喧哗","跑来跑去","交头接耳"]', 0, '安静听讲 means to listen quietly — they are sitting still, listening to the story!', '安静听讲，故事真好听！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0016', 'chi-picword', 3, 'warm', '图上画着太阳公公从东方升起来，天亮了。哪个词语最合适？', '["日落","下雨","日出","下雪"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0017', 'chi-picword', 3, 'warm', '图上画着小鱼在水里摆动尾巴，到处转圈。哪个词语最合适？', '["飞翔","游泳","爬行","奔跑"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0018', 'chi-picword', 3, 'warm', '图上画着几个小朋友在草地上，你追我赶，脚下有个圆圆的球。哪个词语最合适？', '["画画","唱歌","踢球","睡觉"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0019', 'chi-picword', 3, 'warm', '图上画着一朵红花，花瓣张开了，香香的。哪个词语最合适？', '["枯萎","开放","落叶","结冰"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0020', 'chi-picword', 3, 'warm', '图上画着妈妈拿着水壶，往花盆里洒东西。哪个词语最合适？', '["摘花","种树","浇水","扫地"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0021', 'chi-picword', 3, 'warm', '图上画着一只小白兔，它正啃着一根橙色的东西。哪个词语最合适？', '["喝水","吃胡萝卜","睡觉","跑步"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0022', 'chi-picword', 3, 'warm', '图上画着小朋友们排着队，一个一个走进教室。哪个词语最合适？', '["睡觉","跑步","唱歌","排队"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0023', 'chi-picword', 3, 'warm', '图上画着一只小狗，它的尾巴摆来摆去，向主人跑去。哪个词语最合适？', '["睡觉","游泳","摇尾巴","看书"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0024', 'chi-picword', 3, 'retry', '图上画着小明把课本、铅笔都放得整整齐齐，准备去上学。哪个词语最合适？', '["乱扔东西","丢三落四","整理书包","马马虎虎"]', 2, '整理书包 means to tidy up the school bag — everything is neat and ready!', '书包整整齐齐，上学去！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0025', 'chi-picword', 3, 'retry', '图上画着小花给奶奶倒了一杯热茶。哪个词语最合适？', '["调皮捣蛋","孝敬长辈","不懂礼貌","自私自利"]', 1, '孝敬长辈 means to respect and care for elders — 小花 pours tea for grandma!', '孝敬奶奶，真乖！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0026', 'chi-picword', 3, 'retry', '图上画着雨停了，天边出现了一道五颜六色的桥。哪个词语最合适？', '["乌云","太阳","月亮","彩虹"]', 3, '彩虹 means a rainbow — the colourful bridge in the sky after rain!', '彩虹彩虹，五颜六色！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0027', 'chi-picword', 3, 'retry', '图上画着小狗汪汪地叫着，好像在欢迎主人回家。哪个词语最合适？', '["欢迎主人","害怕主人","讨厌主人","不理主人"]', 0, '欢迎主人 means to welcome the owner home — the dog is barking happily!', '汪汪，主人回来啦！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0028', 'chi-picword', 3, 'retry', '图上画着小朋友们在图书馆里轻轻地走路，小声地说话。哪个词语最合适？', '["大声喧哗","保持安静","跑来跑去","追逐打闹"]', 1, '保持安静 means to stay quiet — in the library we walk softly and speak softly!', '图书馆里请安静！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p3-0029', 'chi-picword', 3, 'retry', '图上画着秋天到了，黄色的叶子从树上掉了下来，铺了一地。哪个词语最合适？', '["开花","发芽","落叶","结果"]', 2, '落叶 means fallen leaves — the yellow leaves cover the ground!', '落叶铺满地，金黄金黄！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0001', 'chi-picword', 4, 'quest', '图上画着两个人面对面坐着，你一句我一句，说得眉飞色舞。哪个词语最合适？', '["鸦雀无声","愁眉苦脸","谈笑风生","怒气冲冲"]', 2, '谈笑风生 means chatting happily and lively — they are talking and laughing!', '谈笑风生，好开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0002', 'chi-picword', 4, 'quest', '图上画着一个小男孩站在山顶上，望着远处的美景，脸上带着笑容。哪个词语最合适？', '["胆小如鼠","心旷神怡","垂头丧气","提心吊胆"]', 1, '心旷神怡 means feeling relaxed and happy at a beautiful view!', '站在山顶，心情真好！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0003', 'chi-picword', 4, 'quest', '图上画着一群小朋友围成一圈，认真地听爷爷讲过去的故事。哪个词语最合适？', '["聚精会神","心不在焉","东张西望","交头接耳"]', 0, '聚精会神 means listening with full attention — the children are all ears!', '听爷爷讲故事，真入迷！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0004', 'chi-picword', 4, 'quest', '图上画着一只小猫悄悄地走近一只小老鼠，眼睛盯着它，身体压得很低。哪个词语最合适？', '["大摇大摆","横冲直撞","东奔西跑","蹑手蹑脚"]', 3, '蹑手蹑脚 means walking softly and quietly — the cat is sneaking up!', '小猫悄悄走，别吓跑老鼠！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0005', 'chi-picword', 4, 'quest', '图上画着刚才还下着雨，现在太阳出来了，天边挂着一道彩色的桥，孩子们指着它笑。哪个词语最合适？', '["乌云密布","电闪雷鸣","雨过天晴","大雨倾盆"]', 2, '雨过天晴 means the rain is over and the sky is clear — the sun is out and a rainbow is in the sky!', '雨过天晴，彩虹出来了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0006', 'chi-picword', 4, 'fresh', '图上画着一个小男孩在河边钓鱼，他一动不动地坐着，等了很久。哪个词语最合适？', '["三心二意","专心致志","心不在焉","东张西望"]', 1, '专心致志 means fully focused — the boy sits still, waiting patiently to fish!', '钓鱼要有耐心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0007', 'chi-picword', 4, 'fresh', '图上画着小朋友们把教室打扫得干干净净，桌椅排得整整齐齐。哪个词语最合适？', '["乱七八糟","脏兮兮","破破烂烂","一尘不染"]', 3, '一尘不染 means spotlessly clean — not a speck of dust!', '教室干净得发亮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0008', 'chi-picword', 4, 'fresh', '图上画着一只小狗看到陌生人，汪汪大叫，守在门口不让人进来。哪个词语最合适？', '["忠心耿耿","胆小如鼠","懒懒散散","无精打采"]', 0, '忠心耿耿 means loyal and faithful — the dog guards the door!', '小狗守门，真忠心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0009', 'chi-picword', 4, 'fresh', '图上画着小红每天放学回家，第一件事就是做作业，从不拖拉。哪个词语最合适？', '["拖拖拉拉","马马虎虎","自觉自律","游手好闲"]', 2, '自觉自律 means doing the right thing on your own — 小红 does her homework first!', '自觉的孩子最棒！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0010', 'chi-picword', 4, 'fresh', '图上画着冬天的大雪过后，整个世界都变白了，树上、屋顶上都是白雪。哪个词语最合适？', '["绿树成荫","银装素裹","骄阳似火","春意盎然"]', 1, '银装素裹 means the world dressed in silver white — snow covers everything!', '雪后的世界，白茫茫一片！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0011', 'chi-picword', 4, 'fresh', '图上画着小明和小华一起搭积木，你一块我一块，搭了一座高高的城堡。哪个词语最合适？', '["齐心合力","各自为政","争先恐后","互不相让"]', 0, '齐心合力 means working together with one heart — they built a tall castle together!', '一起搭积木，城堡高高的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0012', 'chi-picword', 4, 'fresh', '图上画着一位老爷爷坐在树下，慢慢地给小朋友们讲故事，孩子们听得入了迷。哪个词语最合适？', '["索然无味","心不在焉","垂头丧气","津津有味"]', 3, '津津有味 means listening with great delight — the children are lost in the story!', '爷爷讲故事，真好听！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0013', 'chi-picword', 4, 'fresh', '图上画着小鸟妈妈一次又一次地把食物送到巢里，喂给嗷嗷待哺的小鸟。哪个词语最合适？', '["置之不理","袖手旁观","无微不至","冷若冰霜"]', 2, '无微不至 means caring in every little way — mum bird feeds her babies again and again!', '鸟妈妈真细心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0014', 'chi-picword', 4, 'fresh', '图上画着小朋友们在草地上放风筝，风筝越飞越高，大家高兴极了。哪个词语最合适？', '["愁眉苦脸","兴高采烈","垂头丧气","提心吊胆"]', 1, '兴高采烈 means full of joy — the kites are flying high and everyone is happy!', '风筝飞得高高的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0015', 'chi-picword', 4, 'fresh', '图上画着小华在跑步比赛中摔倒了，但他爬起来继续跑，坚持到了终点。哪个词语最合适？', '["坚持不懈","半途而废","知难而退","望而却步"]', 0, '坚持不懈 means never giving up — 小华 fell but got up and finished the race!', '坚持到底，就是胜利！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0016', 'chi-picword', 4, 'warm', '图上画着小朋友们在教室里举手发言，一个比一个积极。哪个词语最合适？', '["鸦雀无声","踊跃发言","垂头丧气","东张西望"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0017', 'chi-picword', 4, 'warm', '图上画着一个小女孩扶着一位老奶奶过马路。哪个词语最合适？', '["调皮捣蛋","自私自利","不懂礼貌","尊老爱幼"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0018', 'chi-picword', 4, 'warm', '图上画着小明把地上的香蕉皮捡起来，扔进垃圾桶。哪个词语最合适？', '["爱护环境","乱扔垃圾","不讲卫生","浪费时间"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0019', 'chi-picword', 4, 'warm', '图上画着夜晚的星星一闪一闪，像小眼睛一样眨呀眨。哪个词语最合适？', '["乌云密布","大雨倾盆","星光闪烁","烈日当空"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0020', 'chi-picword', 4, 'warm', '图上画着小朋友们在操场上拔河，大家一起用力拉绳子。哪个词语最合适？', '["各自为政","齐心协力","袖手旁观","无动于衷"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0021', 'chi-picword', 4, 'warm', '图上画着小华看到同学跌倒了，立刻跑过去帮忙。哪个词语最合适？', '["袖手旁观","幸灾乐祸","置之不理","乐于助人"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0022', 'chi-picword', 4, 'warm', '图上画着春天到了，公园里的花都开了，蝴蝶在花丛中飞来飞去。哪个词语最合适？', '["春暖花开","秋高气爽","寒风刺骨","大雪纷飞"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0023', 'chi-picword', 4, 'warm', '图上画着小明考试得了满分，他笑得合不拢嘴。哪个词语最合适？', '["愁眉苦脸","垂头丧气","眉开眼笑","提心吊胆"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0024', 'chi-picword', 4, 'retry', '图上画着小明把自己的零花钱都存进了存钱罐里，一分也不乱花。哪个词语最合适？', '["大手大脚","铺张浪费","勤俭节约","挥金如土"]', 2, '勤俭节约 means being thrifty — 小明 saves every coin!', '存钱罐，越存越多！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0025', 'chi-picword', 4, 'retry', '图上画着小朋友们排着整齐的队伍，一个接一个地走进礼堂。哪个词语最合适？', '["井然有序","乱七八糟","东倒西歪","横七竖八"]', 0, '井然有序 means neat and orderly — the children walk in one by one!', '排队整齐，真好看！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0026', 'chi-picword', 4, 'retry', '图上画着一只小猫蜷缩在角落里，瑟瑟发抖，眼睛里满是害怕。哪个词语最合适？', '["胆大包天","胆小如鼠","威风凛凛","神气十足"]', 1, '胆小如鼠 means as timid as a mouse — the kitten is shaking with fear!', '小猫别怕，乖乖！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0027', 'chi-picword', 4, 'retry', '图上画着小红把作业本上的错字一一改正，写得工工整整。哪个词语最合适？', '["马马虎虎","粗心大意","敷衍了事","一丝不苟"]', 3, '一丝不苟 means careful in every detail — 小红 corrects every mistake neatly!', '一丝不苟，字写得真漂亮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0028', 'chi-picword', 4, 'retry', '图上画着春天的小草从土里探出头来，嫩绿嫩绿的。哪个词语最合适？', '["生机勃勃","死气沉沉","枯枝败叶","冰天雪地"]', 0, '生机勃勃 means full of life — the spring grass is sprouting!', '春天的小草，绿油油！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-picword-p4-0029', 'chi-picword', 4, 'retry', '图上画着小朋友们在海边堆沙堡、捡贝壳，玩得不亦乐乎。哪个词语最合适？', '["愁眉苦脸","不亦乐乎","垂头丧气","闷闷不乐"]', 1, '不亦乐乎 means having so much fun — building sandcastles and collecting shells!', '海边玩沙，真开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-collocation-p3-0001', 'chi-collocation', 3, 'quest', '一___书', '["只","条","本","朵"]', 2, '一本书 — 本 is the measure word for books.', '一本书，打开知识的大门！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-collocation-p3-0002', 'chi-collocation', 3, 'quest', '___作业', '["做","看","听","玩"]', 0, '做作业 means to do homework — 做 goes with 作业.', '做完作业再玩，心里更踏实！', 'bank') on conflict (id) do nothing;
