insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0001', 'chi-sequencing', 3, 'quest', '把下面的句子排成一段通顺的话：①小明起床后，先刷牙洗脸。②然后，他吃早饭，背上书包去上学。③早上七点，小明起床了。', '["①②③","②③①","③①②","③②①"]', 2, '先说起床的时间（③），再说刷牙洗脸（①），最后吃早饭上学（②）。', '排好队，句子就通顺了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0002', 'chi-sequencing', 3, 'quest', '把下面的句子排成一段通顺的话：①小花把种子种在土里。②过了几天，种子发芽了。③小花每天给种子浇水。', '["①②③","①③②","②①③","③①②"]', 1, '先种种子（①），再每天浇水（③），最后种子发芽（②）。', '小种子，快快长大！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0003', 'chi-sequencing', 3, 'quest', '把下面的句子排成一段通顺的话：①小鸟飞到天上，唱起了歌。②太阳升起来了，天亮了。③小鸟醒了，睁开眼睛。', '["②③①","①②③","③①②","②①③"]', 0, '先天亮（②），小鸟醒来（③），再飞上天唱歌（①）。', '早起的鸟儿有虫吃！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0004', 'chi-sequencing', 3, 'quest', '把下面的句子排成一段通顺的话：①妈妈把米洗干净，放进锅里。②不一会儿，香喷喷的米饭做好了。③妈妈把锅放在火上，开始煮饭。', '["①②③","②①③","③②①","①③②"]', 3, '先洗米放进锅（①），再放在火上煮（③），最后饭做好了（②）。', '香喷喷的米饭出锅了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0005', 'chi-sequencing', 3, 'quest', '把下面的句子排成一段通顺的话：①小明穿上雨衣，拿起雨伞。②外面下起了大雨。③小明走出家门，去上学了。', '["①②③","②①③","③①②","②③①"]', 1, '先下雨（②），再穿雨衣拿伞（①），最后出门上学（③）。', '下雨天，雨伞是好朋友！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0006', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小明把画贴在墙上。②小明画了一幅美丽的画。③大家都夸小明画得好。', '["①②③","②①③","③①②","③②①"]', 1, '先画画（②），再贴在墙上（①），最后大家夸他（③）。', '画得真漂亮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0007', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小鸟妈妈飞回来了。②小鸟张开嘴巴，等着吃虫子。③小鸟妈妈把虫子喂给小鸟。', '["②③①","③②①","①②③","①③②"]', 2, '先妈妈飞回来（①），再小鸟张开嘴（②），最后妈妈喂虫子（③）。', '小鸟吃得香香的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0008', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①雨停了，太阳出来了。②天边出现了一道彩虹。③小朋友们跑出家门看彩虹。', '["①②③","②①③","③①②","③②①"]', 0, '先雨停出太阳（①），再出现彩虹（②），最后小朋友们跑出来看（③）。', '彩虹出来了，快来看！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0009', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小花把花插进花瓶里。②花瓶里的花真漂亮。③小花从花园里摘了几朵花。', '["①②③","②③①","③②①","③①②"]', 3, '先摘花（③），再插进花瓶（①），最后花真漂亮（②）。', '花儿真美！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0010', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小明把球踢进了球门。②小明和小伙伴们在踢足球。③大家高兴地欢呼起来。', '["①②③","②①③","③②①","②③①"]', 1, '先踢足球（②），再把球踢进门（①），最后大家欢呼（③）。', '进球啦！大家欢呼！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0011', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①秋天到了，树叶变黄了。②一阵风吹来，树叶落了下来。③地上铺满了金黄的叶子。', '["①②③","②①③","③②①","①③②"]', 0, '先树叶变黄（①），再风吹落叶（②），最后地上铺满叶子（③）。', '秋天真美，金黄金黄！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0012', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小红把牛奶倒进杯子里。②小红喝了一口牛奶。③妈妈把牛奶递给小红。', '["①②③","②③①","③①②","③②①"]', 2, '先妈妈递牛奶（③），再倒进杯子（①），最后喝一口（②）。', '牛奶真好喝！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0013', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小明把风筝放上了天。②小明拿着风筝来到草地上。③风筝在天上飞得高高的。', '["①②③","③②①","②③①","②①③"]', 3, '先来到草地（②），再放上风筝（①），最后风筝飞得高高的（③）。', '风筝飞上天，真高！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0014', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小华把作业交给了老师。②小华认真地做完了作业。③老师夸小华的字写得很漂亮。', '["①②③","②①③","③②①","②③①"]', 1, '先做完作业（②），再交给老师（①），最后老师夸他（③）。', '字写得真漂亮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0015', 'chi-sequencing', 3, 'fresh', '把下面的句子排成一段通顺的话：①小朋友们排好队。②老师带着小朋友们走进教室。③小朋友们坐到座位上。', '["①②③","②①③","③②①","①③②"]', 0, '先排好队（①），再走进教室（②），最后坐到座位上（③）。', '排队整齐，真棒！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0016', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①小猫看见了一只蝴蝶。②小猫跑过去追蝴蝶。③蝴蝶飞走了，小猫只好回家。', '["②①③","③①②","①②③","①③②"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0017', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①小红把书包整理好。②小红背上书包去上学。③早上，小红起床了。', '["①②③","③①②","②③①","③②①"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0018', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①种子长出了绿绿的小芽。②小明把种子种进土里。③小明每天给种子浇水。', '["②③①","①②③","③②①","①③②"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0019', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①小明洗了手。②小明坐下来吃饭。③妈妈把饭菜端上了桌子。', '["①②③","②①③","③②①","③①②"]', 3, '', '', 'bank') on conflict (id) do nothing;
