insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0021', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①小华打开书包，拿出课本。②上课铃响了。③小华坐到座位上，认真听讲。', '["①②③","③①②","②①③","③②①"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0022', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①小狗跑到主人身边。②主人给小狗喂食。③小狗开心地摇尾巴。', '["①②③","②①③","③①②","③②①"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0023', 'chi-sequencing', 3, 'warm', '把下面的句子排成一段通顺的话：①妈妈把衣服放进洗衣机。②洗衣机转了起来。③衣服洗干净了，妈妈把它们晒在阳台上。', '["②①③","③①②","①③②","①②③"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0024', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①小猫喝完了牛奶。②妈妈把牛奶倒进小猫的碗里。③小猫跑过来，喵喵地叫。', '["①②③","①③②","②③①","②①③"]', 2, '先倒牛奶（②），再小猫跑过来（③），最后喝完牛奶（①）。', '小猫喝牛奶，真可爱！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0025', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①小明把种子种在花盆里。②小芽从土里钻了出来。③小明每天浇水、晒太阳。', '["②①③","①③②","②③①","③①②"]', 1, '先种种子（①），再每天浇水晒太阳（③），最后小芽钻出来（②）。', '小芽钻出来了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0026', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①小鸟在枝头唱歌。②天亮了，太阳升起来了。③小鸟飞到枝头上。', '["②③①","①②③","③①②","②①③"]', 0, '先天亮（②），再小鸟飞到枝头（③），最后唱歌（①）。', '小鸟唱歌，真好听！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0027', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①小明穿上衣服。②小明起床了。③小明吃完早饭去上学。', '["①②③","③②①","②③①","②①③"]', 3, '先起床（②），再穿衣服（①），最后吃早饭去上学（③）。', '新的一天开始了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0028', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①小花把画笔收进笔盒。②小花画了一幅画。③小花把画送给了妈妈。', '["①②③","②①③","③②①","③①②"]', 1, '先画画（②），再收画笔（①），最后把画送给妈妈（③）。', '妈妈收到画，真开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p3-0029', 'chi-sequencing', 3, 'retry', '把下面的句子排成一段通顺的话：①天上突然下起了大雨，而且越下越大。②小明赶紧从书包里拿出雨伞，撑开它。③小明撑着雨伞，安全地回到了家。', '["②①③","③①②","①②③","③②①"]', 2, '先下起大雨（①），再赶紧撑开雨伞（②），最后安全地回到家（③）。', '雨伞是好朋友！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0001', 'chi-sequencing', 4, 'quest', '把下面的句子排成一段通顺的话：①他赶紧跑回家，换上干衣服。②放学了，天突然下起了大雨。③小明没有带雨伞，衣服都淋湿了。④第二天，小明感冒了，只好请假在家休息。', '["①②③④","③②④①","②③①④","②①③④"]', 2, '先放学下雨（②），再淋湿（③），然后回家换衣服（①），最后感冒请假（④）。', '下雨天，别忘了带伞！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0002', 'chi-sequencing', 4, 'quest', '把下面的句子排成一段通顺的话：①小明每天坚持练字半小时。②一个月后，他的字越写越漂亮。③以前，小明的字写得歪歪扭扭。④老师夸他进步很大，小明心里美滋滋的。', '["①②③④","③①②④","②③④①","③②①④"]', 1, '先说以前的字不好（③），再说每天练字（①），然后进步（②），最后老师表扬（④）。', '坚持练字，越写越棒！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0003', 'chi-sequencing', 4, 'quest', '把下面的句子排成一段通顺的话：①妈妈把鸡蛋打进碗里，搅一搅。②不一会儿，香喷喷的蛋炒饭做好了。③妈妈把米饭倒进锅里，和鸡蛋一起炒。④妈妈先把锅烧热，倒进一点油。', '["④①③②","①②③④","④③①②","①③④②"]', 0, '先烧热锅倒油（④），再打蛋搅匀（①），然后倒米饭一起炒（③），最后蛋炒饭做好（②）。', '蛋炒饭，香喷喷！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0004', 'chi-sequencing', 4, 'quest', '把下面的句子排成一段通顺的话：①小鸟妈妈每天飞出去找虫子。②小鸟一天天长大，学会了飞翔。③小鸟妈妈在树上搭了一个温暖的窝。④不久，窝里多了几只嗷嗷待哺的小鸟。', '["①②③④","②①③④","①③②④","③①④②"]', 3, '先搭窝（③），再找虫子（①），然后小鸟出生（④），最后小鸟长大飞翔（②）。', '鸟妈妈真辛苦！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0005', 'chi-sequencing', 4, 'quest', '把下面的句子排成一段通顺的话：①小华把垃圾捡起来，扔进垃圾桶。②小华看见地上有一张废纸。③老师夸小华是个讲卫生的好孩子。④小华走在放学的路上。', '["①②③④","④②①③","②④③①","④①②③"]', 1, '先走在路上（④），再看见废纸（②），然后捡起来扔掉（①），最后老师表扬（③）。', '讲卫生，人人夸！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0006', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①小明认真地做作业。②小明把书包放在桌子上。③做完作业，小明把书包整理好。④小明拿出作业本。', '["②③④①","②④①③","①③②④","③④①②"]', 1, '先放书包（②），再拿作业本（④），然后做作业（①），最后整理书包（③）。', '作业做完了，书包整整齐齐！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0007', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①蜜蜂在花丛中采蜜。②公园里一片生机勃勃的景象。③春天来了，桃花开了。④蝴蝶在花丛中飞舞。', '["②①③④","④③②①","④①②③","③①④②"]', 3, '先桃花开（③），再蜜蜂采蜜（①），然后蝴蝶飞舞（④），最后公园生机勃勃（②）。', '春天真美！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0008', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①风筝飞上了天。②小华把风筝拿出来。③风筝越飞越高，小华高兴极了。④小华跑了起来。', '["①②③④","②③④①","①③②④","②④①③"]', 3, '先拿出风筝（②），再跑起来（④），然后风筝飞上天（①），最后越飞越高（③）。', '风筝飞得高高的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0009', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①小朋友们赶紧跑回家。②天渐渐暗了下来。③乌云飘了过来。④雨点落了下来。', '["②①③④","①③②④","③②④①","③④①②"]', 2, '先乌云飘来（③），再天暗下来（②），然后雨点落下（④），最后小朋友们跑回家（①）。', '下雨了，快跑回家！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0010', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①小红用力地搓洗衣服。②小红把脏衣服放进盆里。③衣服洗干净了，小红把它们晾了起来。④小红倒进洗衣粉。', '["②③④①","②④①③","①③②④","③①②④"]', 1, '先放进盆里（②），再倒洗衣粉（④），然后搓洗（①），最后晾起来（③）。', '衣服洗得干干净净！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0011', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①球进了！②小明把球传给小华。③大家欢呼起来。④小华把球踢向球门。', '["①②③④","②①③④","①③②④","②④①③"]', 3, '先传球（②），再踢向球门（④），然后球进了（①），最后大家欢呼（③）。', '进球啦！大家欢呼！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0012', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①小鸟吃到了香喷喷的虫子。②小鸟妈妈嘴里叼着一条虫子。③小鸟妈妈飞回来了。④小鸟张大嘴巴。', '["②③④①","④③②①","①③②④","③②④①"]', 3, '先妈妈飞回来（③），再叼着虫子（②），然后小鸟张大嘴巴（④），最后吃到虫子（①）。', '小鸟吃得香香的！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0013', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①花儿长出了花苞。②小花把花种撒进土里。③花儿开放了，美丽极了。④小花每天浇水、施肥。', '["②①③④","①③②④","②④①③","③④①②"]', 2, '先撒花种（②），再每天浇水施肥（④），然后长出花苞（①），最后花儿开放（③）。', '花儿开放了，真美！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0014', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①水开了，面条在锅里翻滚。②一碗热气腾腾的面条做好了。③妈妈把面条放进锅里。④妈妈把面条捞出来。', '["②③④①","③①④②","①③②④","④①②③"]', 1, '先放进锅里（③），再水开翻滚（①），然后捞出来（④），最后面条做好（②）。', '热气腾腾的面条，真香！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0015', 'chi-sequencing', 4, 'fresh', '把下面的句子排成一段通顺的话：①老奶奶夸小明是个好孩子。②小明看见一位老奶奶提着很重的东西。③小明心里美滋滋的。④小明跑过去帮忙。', '["①②③④","②①③④","①③②④","②④①③"]', 3, '先看见老奶奶（②），再跑过去帮忙（④），然后老奶奶夸他（①），最后心里美滋滋的（③）。', '帮助别人，自己也开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0016', 'chi-sequencing', 4, 'warm', '把下面的句子排成一段通顺的话：①小明吃早饭。②小明起床穿衣。③小明背上书包去上学。④小明刷牙洗脸。', '["②④①③","①②③④","③①②④","②①④③"]', 0, '', '', 'bank') on conflict (id) do nothing;
