insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0021', 'chi-sequencing', 4, 'warm', '把下面的句子排成一段通顺的话：①主人摸了摸小狗的头。②小狗看见了主人。③小狗高兴地叫了起来。④小狗摇着尾巴跑过去。', '["②①③④","③④①②","②④①③","①③②④"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0022', 'chi-sequencing', 4, 'warm', '把下面的句子排成一段通顺的话：①一幅美丽的画完成了。②小花画了一朵红花。③小花拿起画笔。④小花又画了一只蝴蝶。', '["①②③④","②③④①","③④①②","③②④①"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0023', 'chi-sequencing', 4, 'warm', '把下面的句子排成一段通顺的话：①月亮升上了天空。②天黑了。③小朋友们进入了梦乡。④星星出来了。', '["②③④①","②④①③","④①②③","①②③④"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0024', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①小明把画贴在墙上。②小明画了一幅画。③小明把颜料收好。④大家都夸小明画得好。', '["①②③④","③②①④","②③①④","④②③①"]', 2, '先画画（②），再收颜料（③），然后贴在墙上（①），最后大家夸他（④）。', '画得真漂亮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0025', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①小狗跑到小河边。②小狗跳进河里游泳。③小狗爬上岸，甩了甩身上的水。④小狗开心地跑回家。', '["②③④①","①②③④","①③②④","③④①②"]', 1, '先跑到河边（①），再跳进河里（②），然后爬上岸甩水（③），最后开心地跑回家（④）。', '小狗游泳，真开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0026', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①小华把书放回书架。②小华从书架上拿下一本书。③小华坐在椅子上看书。④小华看得入了迷。', '["②③④①","②①③④","①②③④","③②④①"]', 0, '先拿下书（②），再坐下看书（③），然后看得入迷（④），最后把书放回书架（①）。', '看书看得入了迷！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0027', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①秋天到了，农民伯伯开始收割稻谷。②农民伯伯把稻谷割下来，堆成一堆堆。③农民伯伯把稻谷装上车，运回家。④一年的辛苦有了收获。', '["②①③④","④②③①","④①②③","①②③④"]', 3, '先开始收割（①），再割下来堆成堆（②），然后装上车运回家（③），最后有了收获（④）。', '丰收啦，真开心！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0028', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①小明把种子种进花盆。②小明每天给种子浇水。③种子发芽了。④小苗越长越高。', '["②③④①","①②③④","①③②④","③④①②"]', 1, '先种种子（①），再每天浇水（②），然后发芽（③），最后小苗越长越高（④）。', '小苗长高了！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sequencing-p4-0029', 'chi-sequencing', 4, 'retry', '把下面的句子排成一段通顺的话：①天黑了，路灯亮了起来。②小朋友们走在回家的路上。③小朋友们和爸爸妈妈吃晚饭。④吃完晚饭，小朋友们做作业。', '["④③②①","①③②④","①②③④","③④①②"]', 2, '先天黑路灯亮（①），再走在回家的路上（②），然后吃晚饭（③），最后做作业（④）。', '吃完晚饭做作业，真自觉！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0001', 'chi-sentence', 3, 'quest', '把句子写得更生动：小狗跑。(Choose the best expanded sentence.)', '["小狗跑。","小狗在草地上快快乐乐地跑。","小狗跑跑跑。","草地上的狗。"]', 1, '加上在哪里、怎么样跑，句子就生动了：小狗在草地上快快乐乐地跑。', 'A happy dog runs a happy sentence!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0002', 'chi-sentence', 3, 'quest', '小鸟唱歌。Which is the best way to expand it?', '["小鸟在树上唱歌。","小鸟唱歌唱歌。","唱歌的小鸟。","小鸟歌。"]', 0, '加上“在树上”，我们就知道小鸟在哪里唱歌了。', 'Singing birds need a stage — the tree!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0003', 'chi-sentence', 3, 'quest', '仿照句子“天上的白云像棉花”，选出写法一样的句子。', '["地上的落叶像蝴蝶。","白云在天上飘。","棉花是白色的。","天上有很多白云。"]', 0, '两个句子都用“像”，把一样东西比作另一样东西。', 'Clouds like cotton — soft and fluffy!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0004', 'chi-sentence', 3, 'quest', '仿照句子“小鸟唱歌，小鱼游泳”，选出写法一样的句子。', '["小狗跑步，小猫睡觉。","小鸟会唱歌。","小鱼在水里。","唱歌的小鸟很开心。"]', 0, '两个小句子并排，都写小动物在做什么。', 'Animals doing things, two by two!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0005', 'chi-sentence', 3, 'quest', '把两个句子合成一个句子：“小鸟在唱歌。小鸟很快乐。”', '["小鸟快乐地唱歌。","小鸟在唱歌很快乐。","小鸟唱歌，快乐。","快乐的小鸟在唱歌唱歌。"]', 0, '把“快乐”变成“快乐地”，两个句子就合成一句了。', 'Two sentences, one happy bird!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0006', 'chi-sentence', 3, 'fresh', '我读书。Which sentence adds the most detail?', '["我读书。","我坐在书桌前认真地读一本有趣的故事书。","我读读书。","书桌前的我。"]', 1, '加上在哪里、怎么样读、读什么书，句子就详细了。', 'A good sentence tells us more!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0007', 'chi-sentence', 3, 'fresh', '太阳升起来了。Expand it:', '["太阳升起来了升起来了。","太阳。","早上，红红的太阳从东方慢慢地升起来了。","升起来的太阳。"]', 2, '加上时间、颜色、方向和快慢，句子更生动了。', 'The sun rises slowly — and so does a good sentence!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0008', 'chi-sentence', 3, 'fresh', '小猫睡觉。Choose the best expansion:', '["小猫在软软的垫子上睡得香香的。","小猫睡觉睡觉。","小猫睡。","睡觉的小猫。"]', 0, '加上在哪里睡、睡得怎么样，句子就完整了。', 'Sleep tight, little cat — and write tight too!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0009', 'chi-sentence', 3, 'fresh', '小朋友们在操场上玩。Expand with WHAT they play:', '["小朋友们在操场上玩滑梯、荡秋千和捉迷藏，玩得真开心。","小朋友们玩玩玩。","操场上的小朋友们。","小朋友们玩。"]', 0, '写出玩什么、玩得怎么样，句子就丰富了。', 'Slides, swings and hide-and-seek — what a day!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0010', 'chi-sentence', 3, 'fresh', '仿照句子“我爱爸爸，我爱妈妈”，选出写法一样的句子。', '["我爱老师，我爱同学。","爸爸妈妈爱我。","我爱我的家。","老师爱我们。"]', 0, '两个小句子结构一样，都说“我爱……”。', 'Love repeats — and so does a good pattern!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0011', 'chi-sentence', 3, 'fresh', '仿照句子“小明跑得快，小红跑得慢”，选出写法一样的句子。', '["小狗走得快，小猫走得慢。","小明跑步很快。","小红跑得不快。","快跑的小明。"]', 0, '两个小句子都用“……得快，……得慢”，一快一慢相对。', 'Fast and slow — a perfect pair!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0012', 'chi-sentence', 3, 'fresh', '仿照句子“天黑了，星星出来了”，选出写法一样的句子。', '["天亮了，太阳出来了。","星星在天上。","天黑了很可怕。","我看到星星。"]', 0, '两个小句子都写时间变了、东西出来了。', 'Night falls, stars appear — morning too!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0013', 'chi-sentence', 3, 'fresh', '“下雨了。我们不能出去玩。”合成一句：', '["因为下雨了，所以我们不能出去玩。","下雨了我们不能出去玩。","我们不能出去玩下雨了。","下雨不能玩我们。"]', 0, '用“因为……所以……”把原因和结果连起来。', 'Because it rains, so we stay in — cause and effect!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0014', 'chi-sentence', 3, 'fresh', '“妈妈在做饭。爸爸在看报纸。”合成一句：', '["妈妈在做饭，爸爸在看报纸。","妈妈做饭爸爸看报纸。","做饭看报纸妈妈爸爸。","妈妈爸爸做饭看报纸。"]', 0, '用逗号把两个人的动作连成一句话。', 'Mum cooks, Dad reads — one sentence, two people!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0015', 'chi-sentence', 3, 'fresh', '“小狗很可爱。小狗很听话。”合成一句：', '["小狗很可爱，也很听话。","小狗可爱听话很。","可爱听话小狗。","小狗的听话可爱。"]', 0, '用“也”把两个特点连起来，句子更通顺。', 'Cute AND well-behaved — what a good dog!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0016', 'chi-sentence', 3, 'warm', '花儿开了。Expand with WHEN and WHERE:', '["春天，公园里的花儿开了。","花儿开了开了。","花儿开。","公园里的花。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0017', 'chi-sentence', 3, 'warm', '妈妈做饭。Add WHO and WHAT:', '["妈妈在厨房做美味的饭菜。","妈妈做饭做饭。","做饭的妈妈。","妈妈饭。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0018', 'chi-sentence', 3, 'warm', '下雨了。Expand the sentence:', '["下雨了下雨了。","雨下。","今天早上，雨哗哗地下个不停。","下雨的今天。"]', 2, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0019', 'chi-sentence', 3, 'warm', '仿照句子“春天来了，花儿开了”，选出写法一样的句子。', '["秋天来了，树叶黄了。","花儿很美丽。","春天很温暖。","我喜欢春天。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0020', 'chi-sentence', 3, 'warm', '仿照句子“妈妈笑了，爸爸也笑了”，选出写法一样的句子。', '["我跳了，小明也跳了。","妈妈很开心。","爸爸笑了笑。","我和爸爸笑了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0021', 'chi-sentence', 3, 'warm', '仿照句子“红红的太阳，圆圆的月亮”，选出写法一样的句子。', '["高高的山，绿绿的水。","太阳很大。","月亮很圆。","山高水绿。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0022', 'chi-sentence', 3, 'warm', '“我喜欢苹果。我喜欢香蕉。”合成一句：', '["我喜欢苹果和香蕉。","我喜欢苹果，我喜欢香蕉。","苹果香蕉我喜欢。","我喜欢苹果香蕉。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0023', 'chi-sentence', 3, 'warm', '“小明去学校。小明去上课。”合成一句：', '["小明去学校上课。","小明去学校去上课。","学校上课小明。","小明学校，上课。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0024', 'chi-sentence', 3, 'retry', '老师走进教室。Expand:', '["早上，老师微笑着走进教室，同学们马上坐好了。","老师走进教室走进教室。","走进教室的老师。","老师教室。"]', 0, '加上时间、老师的样子和同学们的反应，句子就生动了。', 'The teacher walks in — and the class sits up straight!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0025', 'chi-sentence', 3, 'retry', '小船在水上漂。Expand:', '["一只小船在平静的湖面上慢慢地漂着。","小船漂漂漂。","小船漂。","水上的小船。"]', 0, '加上什么样的船、在哪里、怎么样漂，句子就丰富了。', 'Drifting slowly on a calm lake — lovely!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0026', 'chi-sentence', 3, 'retry', '仿照句子“大象的鼻子长，猴子的尾巴长”，选出写法一样的句子。', '["长颈鹿的脖子长，袋鼠的腿长。","大象鼻子很长。","猴子尾巴很长。","鼻子长尾巴长。"]', 0, '两个小句子结构一样，都说动物的某个部位长。', 'Long noses, long tails, long necks — patterns everywhere!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0027', 'chi-sentence', 3, 'retry', '仿照句子“白天，太阳公公笑了；晚上，月亮姐姐也笑了”，选出写法一样的句子。', '["早上，小鸟唱歌了；晚上，小虫也唱歌了。","太阳公公笑了。","月亮姐姐笑了。","白天晚上都笑了。"]', 0, '两个小句子一白天一晚上，结构一样，还用了“也”。', 'Day and night, everyone smiles!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0028', 'chi-sentence', 3, 'retry', '“小明在看书。小红在写字。”合成一句：', '["小明在看书，小红在写字。","小明看书小红写字。","看书写字小明小红。","小明小红看书写字。"]', 0, '用逗号把两个人的动作连成一句话。', 'One reads, one writes — one sentence!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p3-0029', 'chi-sentence', 3, 'retry', '“天黑了。星星出来了。”合成一句：', '["天黑了，星星出来了。","天黑星星出来了。","星星天黑出来了。","黑了天，星星出来。"]', 0, '用逗号把两件先后发生的事连成一句话。', 'Night falls, stars appear — in one smooth sentence!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0001', 'chi-sentence', 4, 'quest', '弟弟踢足球。Expand with time, place and how:', '["弟弟踢足球。","星期六下午，弟弟在操场上开心地踢足球。","弟弟踢踢足球。","操场上的弟弟。"]', 1, '加上时间、地点和心情，句子就完整生动了。', 'Saturday football — what a kick!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0002', 'chi-sentence', 4, 'quest', '风吹过树林。Make it more vivid:', '["风吹过树林，树叶沙沙地响，好像在唱歌。","风吹风吹。","树林里的风。","风吹过。"]', 0, '加上声音和比喻，句子就生动起来了。', 'The leaves sing when the wind passes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0003', 'chi-sentence', 4, 'quest', '仿照句子“清晨，太阳从东方升起，照亮了大地”，选出写法一样的句子。', '["傍晚，月亮从天边升起，照亮了夜空。","太阳很亮。","清晨很美丽。","大地被照亮了。"]', 0, '两个句子结构一样：时间+东西升起+照亮了什么。', 'Sun by day, moon by night — same pattern!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0004', 'chi-sentence', 4, 'quest', '仿照句子“小鸟在枝头唱歌，好像在说：春天来了！”选出写法一样的句子。', '["小鱼在水里游来游去，好像在说：夏天到了！","小鸟唱歌很好听。","春天来了，花开了。","枝头上的小鸟。"]', 0, '两个句子都用“好像在说”，让小动物说话。', 'Animals talking — what are they saying?', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0005', 'chi-sentence', 4, 'quest', '“小明生病了。小明坚持来上学。”合成一句：', '["虽然小明生病了，但是他还是坚持来上学。","小明生病了坚持来上学。","生病坚持上学小明。","小明生病，上学坚持。"]', 0, '用“虽然……但是……”把转折的意思连起来。', 'Sick but still at school — what a star!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0006', 'chi-sentence', 4, 'fresh', '月亮出来了。Expand with a comparison:', '["月亮出来了。","晚上，弯弯的月亮像一把小镰刀挂在天上。","月亮出来出来。","天上的月亮。"]', 1, '用“像”把月亮比作镰刀，句子更生动了。', 'The moon like a little sickle — how pretty!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0007', 'chi-sentence', 4, 'fresh', '小明画了一幅画。Expand:', '["小明画了一幅美丽的画，画上有红花、绿树和蓝天。","小明画画画。","画画的小明。","小明画。"]', 0, '写出画上有什么，句子就详细了。', 'Red flowers, green trees, blue sky — a lovely picture!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0008', 'chi-sentence', 4, 'fresh', '下雪了。Expand the sentence:', '["冬天到了，天上飘下雪花，大地像铺上了一层白被子。","下雪了下雪了。","下雪的天。","雪下。"]', 0, '加上季节、雪花和比喻，句子更美了。', 'Snow like a white blanket over the earth!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0009', 'chi-sentence', 4, 'fresh', '小明和小红在图书馆看书。Expand:', '["星期六上午，小明和小红安安静静地坐在图书馆里看书。","小明小红看书看书。","图书馆里的小明小红。","小明和小红看书。"]', 0, '加上时间、地点和样子，句子就完整了。', 'Quiet readers in the library — shh!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0010', 'chi-sentence', 4, 'fresh', '仿照句子“雨越下越大，风越刮越猛”，选出写法一样的句子。', '["雪越下越厚，路越走越滑。","雨下得很大。","风刮得很猛。","雨和风都很大。"]', 0, '两个小句子都用“越……越……”，越变越厉害。', 'More and more — the pattern grows!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0011', 'chi-sentence', 4, 'fresh', '仿照句子“如果明天不下雨，我们就去爬山”，选出写法一样的句子。', '["如果今天天气好，我们就去放风筝。","明天天气好，我们去爬山。","我们去爬山吧。","明天不下雨就好了。"]', 0, '两个句子都用“如果……就……”，先说条件，再说结果。', 'If the weather is fine, we fly kites!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0012', 'chi-sentence', 4, 'fresh', '仿照句子“小明不仅学习好，而且体育也很好”，选出写法一样的句子。', '["小红不仅唱歌好，而且跳舞也很好。","小明学习很好。","体育课上小明很好。","小明和小红都很好。"]', 0, '两个句子都用“不仅……而且……”，说出两个优点。', 'Good at this AND good at that — double talent!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0013', 'chi-sentence', 4, 'fresh', '“花儿开了。蜜蜂来了。”合成一句：', '["花儿一开，蜜蜂就来了。","花儿开了蜜蜂来了。","开花蜜蜂来。","花儿蜜蜂开了来了。"]', 0, '用“一……就……”把两件紧接着发生的事连起来。', 'Flowers open, bees arrive — right away!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0014', 'chi-sentence', 4, 'fresh', '“他跑得很快。他得了第一名。”合成一句：', '["因为他跑得很快，所以得了第一名。","他跑得很快得了第一名。","跑得快第一名他。","他第一名跑得很快。"]', 0, '用“因为……所以……”把原因和结果连起来。', 'Fast running, first place — cause and effect!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0015', 'chi-sentence', 4, 'fresh', '“小红喜欢画画。小红喜欢唱歌。”合成一句：', '["小红不但喜欢画画，而且喜欢唱歌。","小红喜欢画画唱歌。","画画唱歌小红喜欢。","小红喜欢画喜欢唱。"]', 0, '用“不但……而且……”把两个爱好连起来。', 'Drawing AND singing — a talented girl!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0016', 'chi-sentence', 4, 'warm', '奶奶讲故事。Expand:', '["每天晚上，奶奶坐在摇椅上，给我讲一个有趣的故事。","奶奶讲故事讲故事。","讲故事的奶奶。","奶奶故事。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0017', 'chi-sentence', 4, 'warm', '小鱼游。Which expansion is the best?', '["小鱼在清清的河水里自由自在地游来游去。","小鱼游游游。","小鱼游。","河水里的小鱼。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0018', 'chi-sentence', 4, 'warm', '我们去公园玩。Add when, who and what you did:', '["星期天早上，我们全家去公园玩滑梯、荡秋千，玩得真开心。","我们去公园玩玩。","去公园的我们。","我们去公园。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0019', 'chi-sentence', 4, 'warm', '仿照句子“虽然下雨了，但是我们还是去上学了”，选出写法一样的句子。', '["虽然天很冷，但是小明还是坚持跑步。","下雨了，我们不上学。","我们去上学，天在下雨。","虽然但是很好。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0020', 'chi-sentence', 4, 'warm', '仿照句子“花园里的花真多啊，有红的，有黄的，还有紫的”，选出写法一样的句子。', '["书包里的书真多啊，有语文书，有数学书，还有图画书。","花园里的花很美。","花有红的黄的。","我喜欢花园。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0021', 'chi-sentence', 4, 'warm', '仿照句子“他一边走路，一边唱歌”，选出写法一样的句子。', '["她一边吃饭，一边看书。","他走路很快。","唱歌很好听。","他走路唱歌。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0022', 'chi-sentence', 4, 'warm', '“这本书很有趣。这本书很有用。”合成一句：', '["这本书不但有趣，而且很有用。","这本书有趣用。","有趣有用这本书。","这本书很有趣用。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0023', 'chi-sentence', 4, 'warm', '“我一回家。我就开始做作业。”合成一句：', '["我一回家就开始做作业。","我回家开始做作业。","回家做作业我一。","我一回家做作业开始。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0024', 'chi-sentence', 4, 'retry', '秋天到了，树叶变黄了。Expand with more detail:', '["秋天到了，金黄的树叶一片一片地从树上飘下来，像一只只蝴蝶在空中飞舞。","秋天到了树叶黄了。","树叶黄了黄了。","秋天的树叶。"]', 0, '加上树叶的样子和比喻，句子更美了。', 'Leaves like butterflies dancing in the air!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0025', 'chi-sentence', 4, 'retry', '小猫追着蝴蝶跑。Expand:', '["一只可爱的小白猫追着一只黄蝴蝶，在花丛中跑来跑去。","小猫跑跑跑。","小猫追蝴蝶。","追蝴蝶的小猫。"]', 0, '加上猫和蝴蝶的样子、在哪里跑，句子就生动了。', 'A white cat chasing a yellow butterfly!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0026', 'chi-sentence', 4, 'retry', '仿照句子“时间像流水一样，一去不回头”，选出写法一样的句子。', '["光阴像箭一样，一去不复返。","时间过得很快。","流水一去不回头。","时间像流水。"]', 0, '两个句子都用“像……一样”做比喻，说时间过得很快。', 'Time flies like an arrow — catch it!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0027', 'chi-sentence', 4, 'retry', '仿照句子“小草从土里钻出来，伸了个懒腰”，选出写法一样的句子。', '["小花从花苞里探出头来，打了个哈欠。","小草钻出来了。","土里有小草。","小草伸懒腰。"]', 0, '两个句子都让植物像人一样动起来。', 'Plants waking up — stretch and yawn!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0028', 'chi-sentence', 4, 'retry', '“风停了。雨也停了。”合成一句：', '["风停了，雨也停了。","风雨停了。","停了风雨。","风停雨停了了。"]', 0, '用逗号和“也”把两件事连成一句话。', 'Wind stops, rain stops — calm at last!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-sentence-p4-0029', 'chi-sentence', 4, 'retry', '“我们去公园。我们去玩游戏。”合成一句：', '["我们去公园玩游戏。","我们去公园去玩游戏。","公园游戏我们去。","我们公园玩游戏去。"]', 0, '把“去公园”和“玩游戏”合成一个动作：去公园玩游戏。', 'Off to the park to play — one smooth sentence!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0001', 'chi-reading', 3, 'quest', '小明每天早上六点起床。他刷牙、洗脸，然后吃早饭。吃完早饭，他背起书包去上学。Question: 小明早上几点起床？', '["六点","七点","八点","五点"]', 0, '短文说：小明每天早上六点起床。', 'Early bird 小明!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0002', 'chi-reading', 3, 'quest', '春天来了。公园里的花开了，有红的、黄的、紫的。小朋友们在公园里放风筝，玩得真开心。Question: 小朋友们在公园里做什么？', '["放风筝","游泳","滑雪","看电视"]', 0, '短文说：小朋友们在公园里放风筝。', 'Fly a kite, catch the wind!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0003', 'chi-reading', 3, 'quest', '小红养了一只小猫。小猫全身白白的，眼睛大大的。它最喜欢吃鱼，还喜欢晒太阳。Question: 小猫最喜欢吃什么？', '["鱼","米饭","青菜","面包"]', 0, '短文说：小猫最喜欢吃鱼。', 'Fish for the cat — yum!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0004', 'chi-reading', 3, 'quest', '小明每天早起，认真读书。他上课专心听讲，作业写得很工整。老师常常夸他是个好学生。Question: 这段话主要讲了什么？', '["小明是个认真学习的好学生。","小明每天早起。","小明上课听讲。","小明写作业。"]', 0, '整段话都在说小明认真学习，是个好学生。', 'A hard-working student — well done!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0005', 'chi-reading', 3, 'quest', '小猫很爱干净。它每天都用舌头舔自己的毛。它的毛总是干干净净的。Question: 给这段话选一个最合适的题目。', '["爱干净的小猫","小猫的毛","小猫的舌头","小猫吃饭"]', 0, '整段话都在写小猫爱干净，所以题目是“爱干净的小猫”最合适。', 'A clean cat is a happy cat!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0006', 'chi-reading', 3, 'fresh', '秋天，树叶变黄了。一片片黄叶从树上飘下来，像一只只黄蝴蝶。地上铺满了金黄的树叶。Question: 树叶像什么？', '["黄蝴蝶","小鸟","白云","雪花"]', 0, '短文说：树叶像一只只黄蝴蝶。', 'Leaves like butterflies — autumn magic!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0007', 'chi-reading', 3, 'fresh', '小明生病了，不能去上学。他躺在床上，妈妈给他倒了一杯温水。妈妈说：“你要多喝水，好好休息。”Question: 妈妈让小明做什么？', '["多喝水，好好休息","去上学","出去玩","看电视"]', 0, '短文说：妈妈说“你要多喝水，好好休息。”', 'Drink water, rest well — Mum knows best!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0008', 'chi-reading', 3, 'fresh', '星期天，爸爸带我去动物园。我们看到了大象、猴子和长颈鹿。我最喜欢看猴子，因为它们很调皮。Question: 我最喜欢看什么动物？', '["猴子","大象","长颈鹿","老虎"]', 0, '短文说：我最喜欢看猴子，因为它们很调皮。', 'Naughty monkeys are the best show!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0009', 'chi-reading', 3, 'fresh', '小丽有一支漂亮的铅笔。铅笔是粉红色的，上面画着一只小兔子。她每天都用它写字。Question: 小丽的铅笔是什么颜色的？', '["粉红色","蓝色","绿色","黄色"]', 0, '短文说：铅笔是粉红色的。', 'A pink pencil with a bunny — cute!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0010', 'chi-reading', 3, 'fresh', '冬天到了，天气很冷。小朋友们穿上厚厚的棉衣，戴上帽子和手套。他们在雪地里堆雪人，玩得真开心。Question: 小朋友们在雪地里做什么？', '["堆雪人","游泳","放风筝","踢足球"]', 0, '短文说：他们在雪地里堆雪人。', 'Snowmen in winter — so much fun!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0011', 'chi-reading', 3, 'fresh', '小狗看到陌生人就汪汪叫。它是家里的好帮手，主人很喜欢它。Question: 给这段话选一个最合适的题目。', '["看家的小狗","小狗的叫声","陌生人来了","主人喜欢狗"]', 0, '整段话都在写小狗看家，所以题目是“看家的小狗”最合适。', 'A good watchdog on duty!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0012', 'chi-reading', 3, 'fresh', '冬天，雪花飘下来，大地白了。小朋友们穿上棉衣，戴上手套，到雪地里堆雪人、打雪仗。Question: 这段话主要写了什么？', '["冬天，小朋友们在雪地里玩。","雪花飘下来。","大地白了。","小朋友们穿棉衣。"]', 0, '整段话主要写冬天小朋友们在雪地里玩。', 'Winter fun in the snow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0013', 'chi-reading', 3, 'fresh', '小丽的书包里有很多书，有语文书、数学书，还有图画书。她每天背着书包去上学。Question: 哪一句话最适合做这段话的结尾？', '["小丽真爱学习啊！","小丽的书包很重。","小丽不喜欢上学。","小丽把书包丢了。"]', 0, '“小丽真爱学习啊！”最能总结这段话。', 'Love learning, love books!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0014', 'chi-reading', 3, 'fresh', '小华的妈妈每天很早就起床。她做好早饭，叫小华起床，然后送小华去上学。Question: 这段话主要讲了什么？', '["妈妈每天早起照顾小华。","妈妈做早饭。","妈妈叫小华起床。","妈妈送小华上学。"]', 0, '整段话主要讲妈妈每天早起照顾小华。', 'Mum wakes up early for us!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0015', 'chi-reading', 3, 'fresh', '公园里有一棵大树。夏天，大树为人们遮挡阳光。人们在大树下乘凉、聊天，真舒服。Question: 给这段话选一个最合适的题目。', '["公园里的大树","夏天真热","人们在聊天","大树的叶子"]', 0, '整段话都在写公园里的大树，所以题目是“公园里的大树”最合适。', 'A big tree gives cool shade!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0016', 'chi-reading', 3, 'warm', '昨天，下了一场大雨。雨停后，天上出现了一道美丽的彩虹。小明站在窗前，高兴地看着彩虹。Question: 雨停后，天上出现了什么？', '["彩虹","太阳","月亮","星星"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0017', 'chi-reading', 3, 'warm', '小华的家后面有一个小花园。花园里种着西红柿和青菜。每天放学后，小华都去给菜浇水。Question: 小华每天放学后去做什么？', '["给菜浇水","踢足球","看电视","写作业"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0018', 'chi-reading', 3, 'warm', '奶奶今年七十岁了。她的头发白了，眼睛也花了。但是，她做的饭菜还是很好吃。Question: 奶奶做的饭菜怎么样？', '["很好吃","很难吃","很咸","很辣"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0019', 'chi-reading', 3, 'warm', '小狗汪汪最爱吃骨头。它每天吃完饭，就跑到院子里玩球。它是一只快乐的小狗。Question: 小狗吃完饭后做什么？', '["跑到院子里玩球","睡觉","看电视","洗澡"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0020', 'chi-reading', 3, 'warm', '春天，燕子从南方飞回来了。它们在屋檐下做窝，叽叽喳喳地叫着，好像在说：春天真好！Question: 这段话主要写了什么？', '["燕子回来了，春天真好。","燕子在做窝。","燕子在叫。","春天来了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0021', 'chi-reading', 3, 'warm', '小红看到一位老奶奶提着很重的东西。她马上跑过去，帮老奶奶提东西。老奶奶笑着说：“谢谢你，好孩子！”Question: 这段话告诉我们什么？', '["我们要帮助别人。","老奶奶提着东西。","小红跑得很快。","老奶奶笑了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0022', 'chi-reading', 3, 'warm', '雨后，空气很新鲜。草地上的小草绿油油的，花儿更鲜艳了。小朋友们都出来玩了。Question: 哪一句话最适合做这段话的结尾？', '["雨后的公园真美丽啊！","雨下得很大。","小朋友们回家了。","花儿都枯萎了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0023', 'chi-reading', 3, 'warm', '小明种了一棵小树。他每天给小树浇水、施肥。小树一天天长大，长出了绿绿的叶子。Question: 这段话主要讲了什么？', '["小明种树，小树长大了。","小明浇水。","小树有叶子。","小明施肥。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0024', 'chi-reading', 3, 'retry', '小红的画参加了学校的画展。她的画画的是一只可爱的小白兔，小白兔正在吃胡萝卜。大家都说她的画画得真好。Question: 给这段话选一个最合适的题目。', '["小红的画","可爱的小白兔","学校的画展","小白兔吃胡萝卜"]', 0, '整段话都在写小红的画，所以题目是“小红的画”最合适。', 'A lovely painting of a bunny!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0025', 'chi-reading', 3, 'retry', '小明不小心把墨水打翻了。他的本子脏了，桌子也脏了。他马上拿来抹布，把桌子擦干净。Question: 这段话告诉我们什么？', '["做错了事要马上改正。","小明打翻了墨水。","小明的本子脏了。","小明拿来了抹布。"]', 0, '小明打翻墨水后马上擦干净，告诉我们做错了事要马上改正。', 'Oops — clean it up, good as new!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0026', 'chi-reading', 3, 'retry', '小鸟在天上飞，小鱼在水里游，小狗在地上跑。它们都有自己的家。Question: 这段话主要讲了什么？', '["小动物们都有自己的家。","小鸟在天上飞。","小鱼在水里游。","小狗在地上跑。"]', 0, '整段话主要讲小动物们都有自己的家。', 'Every animal has a home!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0027', 'chi-reading', 3, 'retry', '小明家养了三条金鱼。一条是红色的，一条是黄色的，一条是黑色的。每天早上，小明都给它们喂食。Question: 小明家养了几条金鱼？', '["三条","两条","四条","五条"]', 0, '短文说：小明家养了三条金鱼。', 'Three little goldfish — count them!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0028', 'chi-reading', 3, 'retry', '早上，太阳升起来了。阳光照在草地上，小草上的露珠闪闪发光。小鸟在枝头快乐地唱歌。Question: 小草上的露珠怎么样？', '["闪闪发光","干干净净","湿湿的","黑黑的"]', 0, '短文说：小草上的露珠闪闪发光。', 'Dewdrops sparkling in the sun!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p3-0029', 'chi-reading', 3, 'retry', '小华很喜欢画画。他画了一幅画，画上有蓝天、白云和绿树。老师夸他的画画得真好。Question: 老师怎么说小华的画？', '["画得真好","画得不好","画得太小","画得太乱"]', 0, '短文说：老师夸他的画画得真好。', 'A star artist in class!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0001', 'chi-reading', 4, 'quest', '小明是三年级的学生。他每天早上六点半起床，七点出门。他走路去学校，大约要走十五分钟。从来没有迟到过。Question: 小明每天早上几点出门？', '["七点","六点半","七点半","八点"]', 0, '短文说：小明七点出门。', 'Seven o''clock — never late!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0002', 'chi-reading', 4, 'quest', '上个星期天，妈妈带我去图书馆。我借了两本书，一本是故事书，一本是科学书。回到家，我马上开始看故事书，看得入了迷。Question: 我在图书馆借了哪两本书？', '["故事书和科学书","故事书和数学书","科学书和语文书","图画书和故事书"]', 0, '短文说：我借了两本书，一本是故事书，一本是科学书。', 'Story book and science book — good choices!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0003', 'chi-reading', 4, 'quest', '小华的家住在五楼。每天放学回家，他都要爬楼梯。虽然很累，但是他从来不抱怨，因为他觉得爬楼梯可以锻炼身体。Question: 小华为什么不抱怨爬楼梯？', '["因为他觉得爬楼梯可以锻炼身体","因为他住在一楼","因为他喜欢楼梯","因为有人帮他"]', 0, '短文说：他觉得爬楼梯可以锻炼身体，所以不抱怨。', 'Climbing stairs keeps him strong!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0004', 'chi-reading', 4, 'quest', '小明从小就喜欢读书。他每天晚上都要看半个小时的书，风雨无阻。慢慢地，他的知识越来越丰富，作文也写得越来越好。Question: 这段话主要告诉我们什么道理？', '["坚持读书会有收获。","小明喜欢看书。","小明作文写得好。","小明每天看书半小时。"]', 0, '小明坚持读书，知识越来越多，告诉我们坚持读书会有收获。', 'Keep reading, keep growing!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0005', 'chi-reading', 4, 'quest', '有一只小鸟，它的翅膀受伤了，飞不起来了。小明发现了它，把它带回家，小心地照顾它。过了几天，小鸟的伤好了，又飞上了蓝天。Question: 给这段话选一个最合适的题目。', '["爱护小鸟","小鸟的翅膀","小明的家","蓝天真美"]', 0, '整段话都在写爱护小鸟，所以题目是“爱护小鸟”最合适。', 'Care for birds — they need us!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0006', 'chi-reading', 4, 'fresh', '有一天，小狗跑到马路中间，差点被车撞到。小明赶紧把它抱回来，对它说：“以后不能再乱跑了，很危险！”Question: 小明为什么把小狗抱回来？', '["因为小狗差点被车撞到","因为小狗很可爱","因为小狗饿了","因为小狗想回家"]', 0, '短文说：小狗差点被车撞到，小明赶紧把它抱回来。', 'Careful, little dog — stay safe!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0007', 'chi-reading', 4, 'fresh', '学校组织了一次春游。同学们早上八点出发，坐了一个小时的车，到了植物园。在植物园里，他们看到了许多美丽的花和大树。Question: 同学们坐了多长时间的车？', '["一个小时","半个小时","两个小时","十五分钟"]', 0, '短文说：同学们坐了一个小时的车到了植物园。', 'One hour on the bus to the gardens!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0008', 'chi-reading', 4, 'fresh', '小明的爷爷今年八十岁了。虽然年纪大了，但是他每天早上还是坚持锻炼身体。他说：“生命在于运动。”Question: 爷爷每天早上做什么？', '["坚持锻炼身体","看电视","睡觉","做饭"]', 0, '短文说：爷爷每天早上还是坚持锻炼身体。', 'Eighty years old and still exercising!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0009', 'chi-reading', 4, 'fresh', '小华很喜欢观察蚂蚁。有一次，他看到一群蚂蚁排着队搬运食物。它们齐心协力，很快就把一块面包搬回了家。Question: 蚂蚁们是怎样搬运食物的？', '["齐心协力","一只一只地搬","用嘴叼着跑","请人帮忙"]', 0, '短文说：蚂蚁们齐心协力搬运食物。', 'Teamwork — ants do it best!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0010', 'chi-reading', 4, 'fresh', '冬天，湖面结冰了。小朋友们在湖边堆雪人、打雪仗。他们的小脸冻得红红的，可是心里却热乎乎的。Question: 小朋友们的小脸为什么红红的？', '["因为被冻的","因为害羞","因为跑步","因为生气"]', 0, '短文说：小朋友们的小脸冻得红红的。', 'Red cheeks in the cold — but warm hearts!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0011', 'chi-reading', 4, 'fresh', '小明的学校后面有一条小河。河水清清的，小鱼在水里自由自在地游来游去。河边种着许多柳树，微风吹过，柳枝轻轻摆动。Question: 给这段话选一个最合适的题目。', '["学校后面的小河","清清的河水","河边的柳树","小鱼在游泳"]', 0, '整段话都在写学校后面的小河，所以题目是“学校后面的小河”最合适。', 'A little river behind the school!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0012', 'chi-reading', 4, 'fresh', '小丽学骑自行车，摔了好几次，膝盖都摔破了。可是她没有放弃，一次又一次地练习。终于，她学会了骑自行车。Question: 这段话主要告诉我们什么？', '["只要不放弃，就一定能成功。","小丽学会了骑自行车。","小丽摔了很多次。","小丽的膝盖摔破了。"]', 0, '小丽摔倒了也不放弃，终于学会了骑车，告诉我们不放弃就能成功。', 'Never give up — you can do it!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0013', 'chi-reading', 4, 'fresh', '秋天，农民伯伯丰收了。金黄的稻谷笑弯了腰，红红的苹果挂满了枝头。大家的脸上都洋溢着丰收的喜悦。Question: 这段话主要写了什么？', '["秋天丰收的景象。","稻谷笑弯了腰。","苹果挂满枝头。","大家很高兴。"]', 0, '整段话主要写秋天丰收的景象。', 'Autumn harvest — golden and happy!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0014', 'chi-reading', 4, 'fresh', '小明有一只小闹钟。每天早上六点，小闹钟就叮铃铃地响起来，叫小明起床。小明再也不迟到了。Question: 哪一句话最适合做这段话的结尾？', '["小闹钟真是我的好帮手！","小闹钟每天六点响。","小明每天六点起床。","小明以前常常迟到。"]', 0, '“小闹钟真是我的好帮手！”最适合做结尾。', 'A little alarm clock, a big helper!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0015', 'chi-reading', 4, 'fresh', '小狗是人类的好朋友。它会看家，还会陪小朋友玩。小朋友们都很喜欢它。Question: 这段话主要讲了什么？', '["小狗是人类的好朋友。","小狗会看家。","小狗会陪小朋友玩。","小朋友们喜欢小狗。"]', 0, '整段话主要讲小狗是人类的好朋友。', 'Dogs are our best friends!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0016', 'chi-reading', 4, 'warm', '小丽的妈妈是一名医生。她每天工作很忙，常常很晚才回家。但是，她还是每天晚上给小丽讲故事，陪她睡觉。Question: 小丽的妈妈是做什么的？', '["医生","老师","护士","工人"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0017', 'chi-reading', 4, 'warm', '奶奶家的院子里种着一棵石榴树。每年秋天，石榴熟了，红红的石榴裂开了嘴，露出了一颗颗红宝石一样的籽儿。Question: 石榴籽像什么？', '["红宝石","珍珠","钻石","红豆"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0018', 'chi-reading', 4, 'warm', '小明和小刚是好朋友。他们一起上学，一起做作业，一起踢足球。有一次，小明生病了，小刚每天放学都去看他，还帮他补课。Question: 小明生病时，小刚做什么？', '["每天放学去看他，帮他补课","和他一起踢足球","和他一起做作业","给他买玩具"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0019', 'chi-reading', 4, 'warm', '春天，农民伯伯在田里播种。他们先把种子撒在土里，再盖上一层薄薄的土，然后浇水。过不了多久，种子就发芽了。Question: 农民伯伯播种时，先做什么？', '["把种子撒在土里","盖上一层土","浇水","施肥"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0020', 'chi-reading', 4, 'warm', '小红第一次参加演讲比赛，心里很紧张。妈妈鼓励她说：“不要怕，大声地说出来，你一定行！”小红听了妈妈的话，勇敢地走上台，讲得很好。Question: 这段话主要讲了什么？', '["在妈妈的鼓励下，小红勇敢地参加了演讲比赛。","小红很紧张。","妈妈鼓励小红。","小红讲得很好。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0021', 'chi-reading', 4, 'warm', '春天，柳树发芽了，桃花开了，小草从土里钻出来。大地换上了绿色的新衣，到处生机勃勃。Question: 哪一句话最适合做这段话的结尾？', '["春天真美啊！","春天很冷。","大地换上了衣服。","小草钻出来了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0022', 'chi-reading', 4, 'warm', '小华做事总是马马虎虎。有一次考试，他把“6”写成了“9”，结果考了很差的分数。从那以后，他做事认真多了。Question: 这段话告诉我们什么道理？', '["做事要认真，不能马虎。","小华考试考得很差。","小华把6写成了9。","小华很马虎。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0023', 'chi-reading', 4, 'warm', '奶奶有一块神奇的手表，那是爷爷送给她的。她每天都戴着它，舍不得摘下来。这块手表对奶奶来说很珍贵。Question: 这块手表为什么对奶奶很珍贵？', '["因为是爷爷送给她的。","因为手表很贵。","因为手表很漂亮。","因为手表是新的。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0024', 'chi-reading', 4, 'retry', '有一天，乌云密布，不一会儿就下起了倾盆大雨。小明没有带伞，被淋成了落汤鸡。回到家，妈妈赶紧给他换上干衣服，还给他煮了一碗热热的姜汤。Question: 这段话主要讲了什么？', '["小明没带伞被雨淋，妈妈照顾他。","天上下起了大雨。","小明被淋成了落汤鸡。","妈妈给小明煮姜汤。"]', 0, '整段话主要讲小明没带伞被雨淋，妈妈照顾他。', 'Mum''s care warms a rainy day!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0025', 'chi-reading', 4, 'retry', '小明的妈妈是一名护士。她每天工作很忙，常常要上夜班。但是，她从来没有抱怨过，总是面带微笑。小明觉得妈妈是世界上最伟大的人。Question: 这段话主要告诉我们什么？', '["妈妈工作很辛苦，但是从不抱怨。","妈妈是一名护士。","妈妈要上夜班。","小明觉得妈妈很伟大。"]', 0, '整段话主要讲妈妈工作很辛苦，但是从不抱怨。', 'Mum works hard and never complains!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0026', 'chi-reading', 4, 'retry', '小华每天放学后，都先写作业，再出去玩。妈妈夸他是个自觉的好孩子。Question: 这段话告诉我们什么？', '["我们要先写作业再玩。","小华每天放学写作业。","妈妈夸小华。","小华出去玩。"]', 0, '小华先写作业再玩，告诉我们要先写作业再玩。', 'Homework first, then play!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0027', 'chi-reading', 4, 'retry', '秋天到了，果园里的苹果红了，梨黄了，葡萄紫了。果农们忙着摘果子，脸上都挂着丰收的笑容。Question: 果农们为什么脸上挂着笑容？', '["因为丰收了","因为天气好","因为果子很贵","因为来了客人"]', 0, '短文说：果农们脸上挂着丰收的笑容。', 'A big harvest brings big smiles!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0028', 'chi-reading', 4, 'retry', '小红很喜欢跳舞。她每个星期六都去上舞蹈课，已经学了两年了。最近，她还参加了学校的舞蹈比赛，得了第一名。Question: 小红学跳舞学了多长时间？', '["两年","一年","三年","半年"]', 0, '短文说：小红学跳舞已经学了两年了。', 'Two years of dancing — and first place!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-reading-p4-0029', 'chi-reading', 4, 'retry', '有一天，小明在路上捡到一个钱包。钱包里有两百块钱和一张身份证。他站在原地等失主，等了半个小时，终于等到了失主。Question: 小明在原地等了多长时间？', '["半个小时","一个小时","十分钟","两个小时"]', 0, '短文说：小明等了半个小时，终于等到了失主。', 'An honest boy waits for the owner!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0001', 'chi-composition', 3, 'quest', '看图写段：图片上，一只小白兔在草地上吃胡萝卜。哪一句最适合做这段话的开头？', '["有一只可爱的小白兔。","胡萝卜很好吃。","草地是绿色的。","小白兔的耳朵很长。"]', 0, '开头先介绍图片上的主要人物：有一只可爱的小白兔。', 'A cute bunny to start the story!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0002', 'chi-composition', 3, 'quest', '看图写段：图片上，小明在公园里放风筝，风筝飞得高高的。哪一句最适合做开头？', '["星期天，小明去公园放风筝。","风筝飞得很高。","公园里有很多人。","小明的风筝是红色的。"]', 0, '开头要说清楚时间、人物和事情：星期天，小明去公园放风筝。', 'Sunday in the park — kite time!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0003', 'chi-composition', 3, 'quest', '看图写段：图片上，妈妈在厨房做饭，香味飘满了整个屋子。哪一句最适合做开头？', '["妈妈做的饭菜真香啊！","厨房里有锅和碗。","香味飘满了屋子。","妈妈在厨房做饭。"]', 3, '开头先说图片上的主要事情：妈妈在厨房做饭。', 'Mum is cooking — yum!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0004', 'chi-composition', 3, 'quest', '看图写段：图片上，下雨了，小红撑着一把红雨伞走在回家的路上。哪一句最适合做开头？', '["下雨了。","小红的雨伞是红色的。","小红走在回家的路上。","雨下得很大。"]', 0, '开头先说天气和事情：下雨了。', 'Rain, rain — don''t forget your umbrella!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0005', 'chi-composition', 3, 'quest', '看图写段：图片上，两个小朋友在沙滩上堆沙堡。哪一句最适合做开头？', '["夏天，两个小朋友在沙滩上堆沙堡。","沙堡很高。","沙滩上有贝壳。","小朋友们很开心。"]', 0, '开头要说清楚时间、人物和事情：夏天，两个小朋友在沙滩上堆沙堡。', 'Summer at the beach — sandcastle time!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0006', 'chi-composition', 3, 'fresh', '看图写段：图片上，小鸟在天上自由地飞翔。哪一句最适合做开头？', '["蓝天上，小鸟自由自在地飞翔。","小鸟有翅膀。","天空是蓝色的。","小鸟飞得很高。"]', 0, '开头先介绍蓝天上的小鸟。', 'Birds flying free in the blue sky!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0007', 'chi-composition', 3, 'fresh', '看图写段：图片上，农民伯伯在田里收割稻谷。哪一句最适合做开头？', '["秋天到了，农民伯伯在田里忙着收割稻谷。","稻谷是金黄色的。","田里有很多稻谷。","农民伯伯很辛苦。"]', 0, '开头要说清楚时间、人物和事情：秋天到了，农民伯伯在收割稻谷。', 'Autumn harvest — golden fields!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0008', 'chi-composition', 3, 'fresh', '看图写段：图片上，小红扶着老奶奶过马路。哪一句最适合做结尾？', '["小红真是个乐于助人的好孩子！","老奶奶年纪大了。","马路上有车。","小红扶着老奶奶。"]', 0, '结尾要赞美小红：她是个乐于助人的好孩子！', 'Helping Grandma cross the road — kind girl!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0009', 'chi-composition', 3, 'fresh', '看图写段：图片上，小明在图书馆里安静地看书。哪一句最适合做开头？', '["星期六上午，小明在图书馆里安静地看书。","图书馆里有很多书。","小明喜欢看书。","书很好看。"]', 0, '开头要说清楚时间、地点和事情：星期六上午，小明在图书馆看书。', 'Saturday in the library — quiet reading!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0010', 'chi-composition', 3, 'fresh', '看图写段：图片上，小鱼在清清的河水里游来游去。哪一句最适合接在“一条小河清清的。”后面？', '["小鱼在水里自由自在地游来游去。","河水是清的。","小鱼有尾巴。","河边有小草。"]', 0, '这句话接在前面最自然，写出小鱼在水里游的样子。', 'Fish swimming happily in the clear river!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0011', 'chi-composition', 3, 'fresh', '看图写段：图片上，雪花飘下来，小朋友们在堆雪人。哪一句最适合做开头？', '["冬天到了，雪花纷纷飘下来。","雪人很可爱。","小朋友们穿着棉衣。","雪是白色的。"]', 0, '开头先说季节和天气：冬天到了，雪花纷纷飘下来。', 'Winter snow — time to build a snowman!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0012', 'chi-composition', 3, 'fresh', '看图写段：图片上，小明和小红一起种树。哪一句最适合做结尾？', '["他们希望小树快快长大。","小树很小。","他们拿着铁锹。","种树很好玩。"]', 0, '结尾要说出他们的希望：希望小树快快长大。', 'Grow, little tree, grow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0013', 'chi-composition', 3, 'fresh', '看图写段：图片上，妈妈在给花浇水，花儿开得真艳。哪一句最适合做开头？', '["早上，妈妈在阳台上给花浇水。","花儿开得真艳。","阳台上有花。","妈妈喜欢花。"]', 0, '开头先说时间、地点和人物：早上，妈妈在阳台上给花浇水。', 'Morning watering — flowers love it!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0014', 'chi-composition', 3, 'fresh', '看图写段：图片上，小狗和小猫一起玩球。哪一句最适合做开头？', '["小狗和小猫是一对好朋友。","球是圆的。","小狗很可爱。","小猫很调皮。"]', 0, '开头先介绍小狗和小猫的关系：它们是一对好朋友。', 'A dog and a cat — best friends!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0015', 'chi-composition', 3, 'fresh', '看图写段：图片上，小朋友们在海边捡贝壳。哪一句最适合做结尾？', '["大家捡了满满一篮贝壳，开心极了！","贝壳很漂亮。","海边有沙子。","小朋友们在海边。"]', 0, '结尾要说出大家的心情：开心极了！', 'A basket full of shells — so happy!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0016', 'chi-composition', 3, 'warm', '看图写段：图片上，一只小鸟站在枝头唱歌。哪一句最适合接在“早上，小鸟站在枝头上。”后面？', '["它快乐地唱着歌，歌声真好听。","枝头是绿色的。","早上很早。","小鸟有翅膀。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0017', 'chi-composition', 3, 'warm', '看图写段：图片上，小狗在草地上追蝴蝶。哪一句最适合做这段话的结尾？', '["小狗玩得真开心啊！","小狗有四条腿。","草地是绿色的。","蝴蝶飞走了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0018', 'chi-composition', 3, 'warm', '看图写段：图片上，爷爷在院子里浇花。哪一句最适合做开头？', '["爷爷每天早上都在院子里浇花。","花儿很美丽。","院子里有很多花。","爷爷年纪大了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0019', 'chi-composition', 3, 'warm', '看图写段：图片上，小明把捡到的钱包还给失主。哪一句最适合做结尾？', '["小明真是个拾金不昧的好孩子！","钱包里有钱。","失主很高兴。","小明在路上走。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0020', 'chi-composition', 3, 'warm', '看图写段：图片上，三个小朋友在操场上踢足球。哪一句最适合做开头？', '["放学后，三个小朋友在操场上踢足球。","足球是圆的。","操场很大。","小朋友们穿着运动鞋。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0021', 'chi-composition', 3, 'warm', '看图写段：图片上，小猫在晒太阳，眯着眼睛，很舒服的样子。哪一句最适合做开头？', '["一只小猫懒洋洋地躺在阳光下晒太阳。","小猫的眼睛眯着。","太阳很大。","小猫很舒服。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0022', 'chi-composition', 3, 'warm', '看图写段：图片上，妈妈给小明讲故事，小明听得津津有味。哪一句最适合接在“每天晚上，妈妈都给小明讲故事。”后面？', '["小明听得津津有味，眼睛都不眨一下。","妈妈会讲故事。","晚上很安静。","小明要睡觉了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
