insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-composition-p3-0024', 'chi-composition', 3, 'retry', '看图写段：图片上，小明在给小鸟喂食。哪一句最适合接在“小明养了一只小鸟。”后面？', '["每天早上，他都给小鸟喂食，还和小鸟说话。","小鸟很可爱。","小明喜欢小鸟。","小鸟会唱歌。"]', 0, '这句话接在前面最自然，写出小明每天给小鸟喂食。', 'Feeding the bird every morning!', 'bank') on conflict (id) do nothing;
