insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0003', 'chi-oral', 3, 'quest', '看图说话：图片上，一只小猫在草地上玩球。第一句说什么最合适？', '["图片上有一只小猫在草地上玩球。","球是圆的。","小猫很可爱。","草地是绿色的。"]', 0, '看图说话先说图片上有什么：有一只小猫在草地上玩球。', 'First, tell us what you see!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0004', 'chi-oral', 3, 'quest', '看图说话：图片上，小明在公园里放风筝。说完“图片上，小明在公园里放风筝”，接下来最适合说什么？', '["风筝飞得高高的，小明笑得很开心。","公园很大。","风筝是红色的。","小明穿着红衣服。"]', 0, '说完图片内容，再说小明的样子和心情。', 'Then tell us more — how happy he is!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0005', 'chi-oral', 3, 'quest', '老师问：“你叫什么名字？”最合适的回答是：', '["我叫小明。","我不知道。","你是谁？","我不告诉你。"]', 0, '回答名字要说“我叫小明”，清楚又有礼貌。', 'My name is 小明 — nice to meet you!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0006', 'chi-oral', 3, 'fresh', '朗读时，遇到“，” （逗号）应该怎么做？', '["停顿一下","停很久","不停顿","读得很快"]', 0, '读到逗号要停顿一下，换一口气。', 'Comma — take a little breath!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0007', 'chi-oral', 3, 'fresh', '朗读时，遇到“。” （句号）应该怎么做？', '["停顿较长，语气下降","不停顿","读得很快","跳过去"]', 0, '读到句号要停顿较长，语气往下降。', 'Full stop — a longer pause!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0008', 'chi-oral', 3, 'fresh', '朗读时，“快乐”的“乐”读第几声？', '["第一声","第二声","第三声","第四声"]', 3, '“快乐”的“乐”读第四声 lè。', '快乐 — lè, fourth tone, happy sound!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0009', 'chi-oral', 3, 'fresh', '朗读“小红跑得快”时，“快”字应该怎么读？', '["读得重一些，读出跑得快的感觉","读得很轻","读得很慢","不读"]', 0, '读“快”字要重一些，读出跑得快的感觉。', 'Run fast — read it fast!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0010', 'chi-oral', 3, 'fresh', '看图说话：图片上，小鸟在枝头唱歌。哪一句说得最生动？', '["小鸟站在枝头上，快乐地唱着歌，歌声真好听。","小鸟在唱歌。","枝头上有小鸟。","小鸟有翅膀。"]', 0, '这句话最生动，写出了小鸟唱歌的样子和歌声。', 'A lively sentence makes the bird sing!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0011', 'chi-oral', 3, 'fresh', '看图说话：图片上，爷爷在院子里浇花。下面哪一句应该先说？', '["图片上，爷爷在院子里浇花。","爷爷很喜欢花。","花儿开得很美。","爷爷年纪大了。"]', 0, '看图说话先说图片上的主要内容：爷爷在院子里浇花。', 'Start with the main thing you see!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0012', 'chi-oral', 3, 'fresh', '看图说话：图片上，小狗在追蝴蝶。哪一句说得最完整？', '["一只小狗在草地上追着蝴蝶跑，玩得真开心。","小狗追蝴蝶。","蝴蝶飞走了。","草地上有小狗。"]', 0, '“一只小狗在草地上追着蝴蝶跑，玩得真开心”说得最完整。', 'A full sentence, a happy dog!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0013', 'chi-oral', 3, 'fresh', '小红说：“我们一起去公园玩吧！”你不想去，应该怎么说？', '["对不起，我今天要写作业，下次再去吧。","不去！","我不喜欢你。","走开，别烦我。"]', 0, '不想去也要有礼貌地说原因，并说下次再去。', 'Polite words keep friends!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0014', 'chi-oral', 3, 'fresh', '客人来家里，你应该说什么？', '["请进，请坐。","你来干什么？","快走吧。","我不认识你。"]', 0, '客人来了，要请客人进来、请坐。', 'Welcome, please come in!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0015', 'chi-oral', 3, 'fresh', '你不小心踩到了同学的脚，应该说什么？', '["对不起，我不是故意的。","是你自己不小心。","活该。","没看到。"]', 0, '不小心踩到别人，要马上说“对不起”。', 'Oops — 对不起！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0016', 'chi-oral', 3, 'warm', '朗读时，“小明”的“明”读第几声？', '["第一声","第二声","第三声","第四声"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0017', 'chi-oral', 3, 'warm', '朗读“我爱我的祖国”时，哪个词要读得重一些？', '["爱","我","的","祖国"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0018', 'chi-oral', 3, 'warm', '朗读时，“学校”的“校”读第几声？', '["第一声","第二声","第三声","第四声"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0019', 'chi-oral', 3, 'warm', '看图说话：图片上，妈妈在厨房做饭。应该先说什么？', '["先说图片上有什么，再说他们在做什么。","先说自己的名字。","先说天气。","先说做饭很难。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0020', 'chi-oral', 3, 'warm', '看图说话：图片上，两个小朋友在沙滩上堆沙堡。哪一句说得最完整？', '["两个小朋友在沙滩上开心地堆沙堡。","沙堡。","小朋友们。","沙滩上。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0021', 'chi-oral', 3, 'warm', '看图说话：图片上，下雨了，小红打着伞回家。哪一句说得最好？', '["下雨了，小红打着一把红伞走在回家的路上。","小红回家。","雨伞是红色的。","下雨了，回家。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0022', 'chi-oral', 3, 'warm', '同学说：“谢谢你帮我捡铅笔。”你应该说：', '["不用谢。","这是我的铅笔。","你真笨。","走开。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0023', 'chi-oral', 3, 'warm', '妈妈问：“你今天在学校过得怎么样？”最合适的回答是：', '["今天过得很好，我学了很多新知识。","不知道。","我不想说。","学校。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0024', 'chi-oral', 3, 'retry', '朗读时，“太阳”的“阳”读第几声？', '["第一声","第二声","第三声","第四声"]', 1, '“阳”读第二声 yáng。', '太阳 — yáng, second tone, warm and bright!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0025', 'chi-oral', 3, 'retry', '朗读时，遇到“？” （问号）应该怎么读？', '["语调上扬，像在问问题","语调下降","不停顿","读得很快"]', 0, '读到问号，语调要往上扬，像在问问题。', 'Question mark — voice goes up!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0026', 'chi-oral', 3, 'retry', '看图说话：图片上，三个小朋友在操场上踢足球。说完图片上的内容，最后可以说什么？', '["小朋友们玩得真开心啊！","足球是圆的。","操场很大。","小朋友们穿着鞋。"]', 0, '说完图片内容，最后可以说出自己的感受。', 'End with how you feel!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0027', 'chi-oral', 3, 'retry', '看图说话：图片上，小明把钱包还给失主。哪一句说得最好？', '["小明捡到钱包后，马上把钱包还给了失主。","小明捡到钱包。","失主很高兴。","钱包里有钱。"]', 0, '“小明捡到钱包后，马上把钱包还给了失主”说得最好。', 'An honest boy — tell his story well!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0028', 'chi-oral', 3, 'retry', '同学问：“你能借我一支笔吗？”你应该怎么回答？', '["当然可以，给你。","不行。","你自己没有吗？","走开。"]', 0, '同学借笔，要大方地说“当然可以，给你”。', 'Sharing is caring!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p3-0029', 'chi-oral', 3, 'retry', '早上见到老师，你应该说什么？', '["老师，早上好！","老师，你来了。","老师，再见。","老师，我走了。"]', 0, '早上见到老师，要说“老师，早上好！”', 'Good morning, teacher!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0001', 'chi-oral', 4, 'quest', '朗读“一个苹果”时，“一”读第几声？', '["第一声","第二声","第三声","第四声"]', 1, '“一”在第四声“个”前面读第二声 yí。', '一会变声，真调皮！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0002', 'chi-oral', 4, 'quest', '朗读“一天”时，“一”读第几声？', '["第一声","第二声","第三声","第四声"]', 3, '“一”在第一声“天”前面读第四声 yì。', '一天 — yì, fourth tone!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0003', 'chi-oral', 4, 'quest', '看图说话：图片上，秋天，果园里瓜果飘香，果农们忙着摘果子。第一句说什么最合适？', '["秋天到了，果园里瓜果飘香，丰收的景象真美！","苹果是红色的。","果农们在摘果子。","秋天很凉爽。"]', 0, '看图说话先说时间、地点和丰收的景象。', 'Autumn harvest — start with the season!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0004', 'chi-oral', 4, 'quest', '看图说话：图片上，小明第一次骑自行车，摔倒了又爬起来。哪一句说得最好？', '["小明第一次学骑自行车，虽然摔倒了，但是他没有放弃，又爬起来继续练习。","小明摔倒了。","自行车有两个轮子。","小明学骑车。"]', 0, '这句话最完整，写出了小明摔倒了也不放弃。', 'Fall down, get up — keep going!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0005', 'chi-oral', 4, 'quest', '老师问：“你为什么迟到了？”你应该怎么回答？', '["对不起，老师，我今天起晚了，以后我会早点起床。","我不知道。","路上堵车。","我不想说。"]', 0, '迟到了要先说“对不起”，说出原因，并保证以后早起。', 'Sorry I''m late — I''ll be early tomorrow!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0006', 'chi-oral', 4, 'fresh', '朗读“小鸟唱歌，唱得真好听”时，哪个词要读得重一些？', '["真好听","小鸟","唱歌","唱得"]', 0, '朗读时要重读“真好听”，读出赞美的语气。', 'Read the praise loud and clear!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0007', 'chi-oral', 4, 'fresh', '朗读时，遇到“……” （省略号）应该怎么做？', '["停顿较长，表示话还没有说完","读得很快","不停顿","跳过去不读"]', 0, '读到省略号要停顿较长，表示话还没有说完。', 'Dot dot dot — the story goes on!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0008', 'chi-oral', 4, 'fresh', '朗读“妈妈，您辛苦了！”时，应该用什么语气？', '["感激、亲切的语气","生气的语气","害怕的语气","冷淡的语气"]', 0, '对妈妈说话要用感激、亲切的语气。', 'Thank you, Mum — read it with love!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0009', 'chi-oral', 4, 'fresh', '朗读时，“兴奋”的“兴”读第几声？', '["第一声","第二声","第三声","第四声"]', 0, '“兴奋”的“兴”读第一声 xīng，和“高兴”的“兴”读音不一样。', '同一个字，不同的音——中文真有趣！', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0010', 'chi-oral', 4, 'fresh', '看图说话：图片上，夜晚，月亮升起来了，星星一闪一闪的。哪一句说得最生动？', '["夜空中，弯弯的月亮升起来了，星星一闪一闪地眨着眼睛。","月亮升起来了。","星星很多。","夜晚很黑。"]', 0, '这句话最生动，写出了月亮和星星的样子。', 'The moon and stars — a lively picture!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0011', 'chi-oral', 4, 'fresh', '看图说话：图片上，小明在图书馆里认真地读书，忘记了时间。下面哪一句应该最后说？', '["小明真是个爱读书的好孩子啊！","小明在图书馆读书。","图书馆里很安静。","小明忘了时间。"]', 0, '看图说话最后可以说出自己的感受或赞美。', 'End with a happy thought!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0012', 'chi-oral', 4, 'fresh', '看图说话：图片上，妈妈生病了，小红给妈妈倒水、盖被子。哪一句说得最好？', '["妈妈生病了，小红细心地照顾妈妈，给她倒水，还给她盖上被子。","妈妈生病了。","小红倒水。","被子很暖和。"]', 0, '“妈妈生病了，小红细心地照顾妈妈”说得最好。', 'A caring daughter — tell it well!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0013', 'chi-oral', 4, 'fresh', '小明想请小红帮忙，但是小红很忙。小明应该怎么说？', '["小红，你现在忙吗？如果你有空，能帮我一个忙吗？","你必须帮我！","你不帮我，我就不理你了。","快帮我！"]', 0, '请别人帮忙要先问对方忙不忙，要有礼貌。', 'Polite asking gets a happy yes!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0014', 'chi-oral', 4, 'fresh', '你在图书馆里，说话声音太大了，管理员提醒你。你应该说：', '["对不起，我会小声一点。","我说话不大声。","你管得着吗？","我不说话了。"]', 0, '被提醒了，要马上说“对不起”，并小声说话。', 'Sorry — I''ll whisper!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0015', 'chi-oral', 4, 'fresh', '同学邀请你去他家玩，但是你今天要去上兴趣班。你应该怎么说？', '["谢谢你的邀请，但是我今天要去上兴趣班，我们改天再约吧。","不去！","我不想去你家。","你自己去玩吧。"]', 0, '不能去也要谢谢邀请，说出原因，并约好下次。', 'Thank you — let''s meet another day!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0016', 'chi-oral', 4, 'warm', '朗读“不是”时，“不”读第几声？', '["第一声","第二声","第三声","第四声"]', 1, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0017', 'chi-oral', 4, 'warm', '朗读“不好”时，“不”读第几声？', '["第一声","第二声","第三声","第四声"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0018', 'chi-oral', 4, 'warm', '朗读“一起”时，“一”读第几声？', '["第一声","第二声","第三声","第四声"]', 3, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0019', 'chi-oral', 4, 'warm', '看图说话：图片上，雨后，彩虹挂在天边，小朋友们跑出家门。说完“雨停了，一道彩虹挂在天边”，接下来最适合说什么？', '["小朋友们高兴地跑出家门，抬头看着美丽的彩虹。","彩虹有七种颜色。","雨下得很大。","小朋友们回家了。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0020', 'chi-oral', 4, 'warm', '看图说话：图片上，同学们在植树节种树，大家干得热火朝天。应该按照什么顺序说？', '["先说时间、地点，再说人物在做什么，最后说自己的感受。","先说自己的感受。","随便说，想说什么就说什么。","先说树的名字。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0021', 'chi-oral', 4, 'warm', '看图说话：图片上，小红把伞借给同学，自己淋着雨回家。哪一句说得最完整？', '["下雨了，小红把自己的伞借给没带伞的同学，自己淋着雨回家。","小红借伞给同学。","雨下得很大。","同学没带伞。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0022', 'chi-oral', 4, 'warm', '同学不小心把你的书弄湿了，他向你道歉。你应该说：', '["没关系，下次小心一点就好了。","你赔我的书！","我再也不理你了。","你真讨厌。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0023', 'chi-oral', 4, 'warm', '妈妈问：“你长大了想做什么？”最合适的回答是：', '["我想当一名老师，因为我想帮助更多的小朋友学习。","不知道。","我想玩游戏。","我不想长大。"]', 0, '', '', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0024', 'chi-oral', 4, 'retry', '朗读“我们一定要好好学习！”时，哪个词要读得重一些？', '["一定","我们","要","学习"]', 0, '朗读时要重读“一定”，读出决心。', '一定 — read it with determination!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0025', 'chi-oral', 4, 'retry', '朗读时，遇到“ ” （引号）里面的话，应该怎么读？', '["像那个人说话一样读","读得很轻","跳过去不读","读得很快"]', 0, '引号里面的话要像那个人说话一样读。', 'Read the words as if you are that person!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0026', 'chi-oral', 4, 'retry', '看图说话：图片上，小朋友们在操场上举行拔河比赛。第一句说什么最合适？', '["运动会上，一场激烈的拔河比赛开始了。","拔河很好玩。","操场上有很多人。","大家齐心协力。"]', 0, '看图说话先说运动会和拔河比赛开始了。', 'Start with the big event!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0027', 'chi-oral', 4, 'retry', '看图说话：图片上，小狗和小猫一起玩球，玩得真开心。哪一句说得最生动？', '["小狗和小猫在草地上玩球，你追我赶，玩得真开心。","小狗和小猫在玩球。","球是圆的。","草地是绿色的。"]', 0, '这句话最生动，写出了小狗和小猫玩的样子。', 'Chasing and playing — so much fun!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0028', 'chi-oral', 4, 'retry', '你看到一位老奶奶提着很重的东西，你想帮助她。你应该说什么？', '["奶奶，我来帮您提吧。","奶奶，你的东西很重。","奶奶，你自己提吧。","奶奶，你走得真慢。"]', 0, '想帮助别人，要主动说“我来帮您”。', 'Let me help you, Grandma!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-oral-p4-0029', 'chi-oral', 4, 'retry', '老师夸你的作文写得很好，你应该说什么？', '["谢谢老师，我会继续努力的。","那当然，我最厉害了。","老师，你真有眼光。","这没什么。"]', 0, '被夸奖了，要说“谢谢老师，我会继续努力的”。', 'Thank you, teacher — I''ll keep trying!', 'bank') on conflict (id) do nothing;
insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-family-p3-0001', 'chi-family', 3, 'fresh', '“家”字一共有几画？', '["10画","8画","9画","11画"]', 0, '“家”一共是10画。', '家有10画——数一数！', 'bank') on conflict (id) do nothing;
