insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-family-p3-0003', 'chi-family', 3, 'fresh', '写“木”字时，最后一笔是什么？', '["捺","横","竖","撇"]', 0, '“木”的最后一笔是捺，像小树伸出枝叶。', '一捺写完，木字完成！', 'bank') on conflict (id) do nothing;
