insert into public.sb_questions (id, topic, level, sub_topic, stem, options, answer, explanation, joke, source) values ('chi-family-p4-0002', 'chi-family', 4, 'fresh', '“田”字一共有几画？', '["5画","4画","6画","7画"]', 0, '“田”一共是5画。', '田字五画，方方正正！', 'bank') on conflict (id) do nothing;
